"use client";

import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import {
  ChevronLeft,
  ChevronRight,
  ExternalLink,
  MapPin,
  RotateCcw,
  Route,
  Trash2,
  X,
} from "lucide-react";
import AdminDateRangeCalendar from "@/components/admin/AdminDateRangeCalendar";
import AdminTripMap, {
  type TripMapPoint,
} from "@/components/admin/AdminTripMap";
import { VEHICLES, type VehicleKey } from "@/lib/config/vehicles";
import { AdminPageHeader } from "@/components/admin/layout";

type RidePassenger = {
  tripId?: string;
  userId?: string;
  numberOfPassengers?: number;
  tripCost?: number;
  pickupOrder?: number;
  dropoffOrder?: number;
};

type RidePassengerDetail = {
  userId: string;
  tripId?: string;
  pickupOrder?: number;
  dropoffOrder?: number;
  numberOfPassengers: number;
  status?: string;
  user?: {
    userNumber?: number;
    name?: string;
    phone?: string;
    profilePic?: string | null;
  } | null;
};

type RideRouteStop = {
  point?: { address?: string; lat?: number; lng?: number };
  arrival?: string;
  departure?: string;
  boarding?: RidePassenger[];
  alighting?: RidePassenger[];
  boardingNumber?: number;
  alightingNumber?: number;
  waitingMinutes?: number;
};

interface RideRow {
  _id: string;
  rideNumber?: number | null;
  date: string;
  startTime: string;
  endTime: string;
  vehicleType: string;
  rideType: string;
  status: string;
  needsManualAssignment?: boolean;
  totalCost: number;
  driverId?: {
    _id?: string;
    name?: string;
    phone?: string;
    email?: string;
  } | null;
  assignedDriver?: {
    name?: string;
    phone?: string;
    carBrand?: string;
    carModel?: string;
    plate?: string;
  } | null;
  passengers?: RidePassenger[];
  route?: RideRouteStop[];
  pickupStation?: { name?: string };
  dropoffStation?: { name?: string };
  availability?: {
    availabilityNumber?: number;
    startTime?: string;
    endTime?: string;
    status?: string;
  } | null;
  passengerDetails?: RidePassengerDetail[];
}

type SearchMode = "rideNumber" | "driverNumber";

const SEARCH_MODES: {
  value: SearchMode;
  label: string;
  placeholder: string;
}[] = [
  { value: "rideNumber", label: "Ride number", placeholder: "e.g. 330" },
  { value: "driverNumber", label: "Driver number", placeholder: "e.g. 87" },
];

const PAGE_SIZE = 20;

const STATUS_STYLES: Record<
  string,
  { bg: string; color: string; label?: string }
> = {
  matched: { bg: "var(--color-secondary-tint)", color: "var(--color-secondary)", label: "Matched" },
  confirmed: {
    bg: "var(--color-secondary-tint)",
    color: "var(--color-secondary-deep)",
    label: "Confirmed",
  },
  active: { bg: "var(--color-warning-tint)", color: "var(--color-warning)", label: "Active" },
  completed: {
    bg: "var(--color-primary-tint)",
    color: "var(--color-muted)",
    label: "Completed",
  },
  cancelled: {
    bg: "var(--color-danger-tint)",
    color: "var(--color-danger)",
    label: "Cancelled",
  },
};

function getStatusStyle(status: string) {
  const key = status?.toLowerCase() ?? "";
  return (
    STATUS_STYLES[key] ?? {
      bg: "var(--color-primary-tint)",
      color: "var(--color-muted)",
      label: status,
    }
  );
}

function initials(name?: string) {
  if (!name) return "—";
  const parts = name.trim().split(/\s+/);
  return parts
    .slice(0, 2)
    .map((p) => p[0]?.toUpperCase())
    .join("");
}

function to12h(hhmm: string): string {
  if (!hhmm) return "—";
  const [h, m] = hhmm.split(":").map(Number);
  const ampm = h >= 12 ? "PM" : "AM";
  return `${h % 12 || 12}:${String(m).padStart(2, "0")} ${ampm}`;
}

function ridePassengers(ride: Pick<RideRow, "passengers" | "route">) {
  if (ride.passengers?.length) return ride.passengers;

  const passengersByTrip = new Map<string, RidePassenger>();
  for (const stop of ride.route ?? []) {
    for (const passenger of [
      ...(stop.boarding ?? []),
      ...(stop.alighting ?? []),
    ]) {
      const tripId = passenger.tripId;
      if (tripId && !passengersByTrip.has(tripId)) {
        passengersByTrip.set(tripId, passenger);
      }
    }
  }
  return [...passengersByTrip.values()];
}

function passengerCount(ride: Pick<RideRow, "passengers" | "route">) {
  const passengers = ridePassengers(ride);
  if (passengers.length) {
    return passengers.reduce(
      (total, passenger) => total + (passenger.numberOfPassengers ?? 1),
      0,
    );
  }
  return (ride.route ?? []).reduce(
    (total, stop) => total + (stop.boardingNumber ?? 0),
    0,
  );
}

function rideMapPoints(
  ride: Pick<RideRow, "route" | "pickupStation" | "dropoffStation">,
): TripMapPoint[] {
  const routePoints: TripMapPoint[] = [];
  for (const [index, stop] of (ride.route ?? []).entries()) {
    const { lat, lng, address } = stop.point ?? {};
    if (
      typeof lat !== "number" ||
      typeof lng !== "number" ||
      !Number.isFinite(lat) ||
      !Number.isFinite(lng)
    ) {
      continue;
    }
    routePoints.push({
      lat,
      lng,
      label: `${index + 1}. ${address ?? "Route stop"}`,
      kind: "stop",
      order: index + 1,
    });
  }

  if (routePoints.length) return routePoints;

  const stationPoints: TripMapPoint[] = [];
  for (const [index, station] of [
    ride.pickupStation,
    ride.dropoffStation,
  ].entries()) {
    const point = station as
      | { name?: string; lat?: number; lng?: number }
      | undefined;
    const lat = point?.lat;
    const lng = point?.lng;
    if (
      typeof lat !== "number" ||
      typeof lng !== "number" ||
      !Number.isFinite(lat) ||
      !Number.isFinite(lng)
    ) {
      continue;
    }
    stationPoints.push({
      lat,
      lng,
      label:
        point?.name ?? (index === 0 ? "Pickup station" : "Dropoff station"),
      kind: index === 0 ? "pickup" : "dropoff",
      order: index + 1,
    });
  }
  return stationPoints;
}

function googleMapsUrl(points: TripMapPoint[]) {
  if (points.length < 2) return null;
  const [origin, ...remaining] = points;
  const destination = remaining.pop();
  if (!origin || !destination) return null;

  const params = new URLSearchParams({
    api: "1",
    origin: `${origin.lat},${origin.lng}`,
    destination: `${destination.lat},${destination.lng}`,
    travelmode: "driving",
  });
  if (remaining.length) {
    params.set(
      "waypoints",
      remaining.map((point) => `${point.lat},${point.lng}`).join("|"),
    );
  }
  return `https://www.google.com/maps/dir/?${params.toString()}`;
}

export default function AdminRidesPage() {
  const [rides, setRides] = useState<RideRow[]>([]);
  const [totalCount, setTotalCount] = useState(0);
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchInput, setSearchInput] = useState("");
  const [searchMode, setSearchMode] = useState<SearchMode>("rideNumber");
  const [range, setRange] = useState({ dateFrom: "", dateTo: "" });
  const [filters, setFilters] = useState({
    q: "",
    searchBy: "rideNumber" as SearchMode,
    dateFrom: "",
    dateTo: "",
    vehicleType: "",
    rideType: "",
    status: "",
    needsManualAssignment: false,
  });
  const [reloadKey, setReloadKey] = useState(0);
  const [detailId, setDetailId] = useState<string | null>(null);
  const [detail, setDetail] = useState<RideRow | null>(null);
  const [detailLoading, setDetailLoading] = useState(false);
  const [detailError, setDetailError] = useState<string | null>(null);
  const [passengerActionTripId, setPassengerActionTripId] = useState<
    string | null
  >(null);
  const [passengerActionError, setPassengerActionError] = useState<
    string | null
  >(null);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [pendingDeleteIds, setPendingDeleteIds] = useState<string[] | null>(
    null,
  );
  const [password, setPassword] = useState("");
  const [deleting, setDeleting] = useState(false);
  const [deleteError, setDeleteError] = useState<string | null>(null);
  const [drivers, setDrivers] = useState<
    { _id: string; name: string; phone?: string; verificationStatus?: string }[]
  >([]);
  const [assignDriverByRide, setAssignDriverByRide] = useState<
    Record<string, string>
  >({});
  const [assigningRideId, setAssigningRideId] = useState<string | null>(null);
  const [assignError, setAssignError] = useState<string | null>(null);

  const detailMapPoints = useMemo(
    () => (detail ? rideMapPoints(detail) : []),
    [detail],
  );
  const detailGoogleMapsUrl = useMemo(
    () => googleMapsUrl(detailMapPoints),
    [detailMapPoints],
  );

  function refresh() {
    setLoading(true);
    setReloadKey((key) => key + 1);
  }

  useEffect(() => {
    fetch("/api/admin/drivers")
      .then((res) => (res.ok ? res.json() : null))
      .then((json) => {
        if (json?.drivers) setDrivers(json.drivers);
      })
      .catch(() => {});
  }, []);

  async function assignDriver(rideId: string) {
    const driverId = assignDriverByRide[rideId];
    if (!driverId) {
      setAssignError("Choose a driver to assign.");
      return;
    }
    setAssigningRideId(rideId);
    setAssignError(null);
    try {
      const res = await fetch(`/api/admin/rides/${rideId}/reassign`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ driverId }),
      });
      const data = await res.json().catch(() => null);
      if (!res.ok) throw new Error(data?.error ?? "Failed to assign driver");
      refresh();
    } catch (err) {
      setAssignError(err instanceof Error ? err.message : "Failed to assign driver");
    } finally {
      setAssigningRideId(null);
    }
  }

  async function deleteRide(id: string) {
    const confirmed = window.confirm(
      "Permanently delete this ride? Its trips will return to the available pool.",
    );
    if (!confirmed) return;
    try {
      const res = await fetch(`/api/admin/rides/${id}`, { method: "DELETE" });
      const data = await res.json().catch(() => null);
      if (!res.ok) throw new Error(data.error ?? "Failed to delete ride");
      setRides((current) => current.filter((ride) => ride._id !== id));
      setTotalCount((current) => Math.max(0, current - 1));
      refresh();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to delete ride");
    }
  }

  async function deleteSelectedRides() {
    if (!pendingDeleteIds?.length) return;
    if (!password.trim()) {
      setDeleteError("Admin password is required.");
      return;
    }
    setDeleting(true);
    setDeleteError(null);
    try {
      const res = await fetch("/api/admin/rides", {
        method: "DELETE",
        headers: {
          "Content-Type": "application/json",
          "x-admin-password": password,
        },
        body: JSON.stringify({ ids: pendingDeleteIds }),
      });
      const data = await res.json().catch(() => null);
      if (!res.ok)
        throw new Error(data?.error ?? "Failed to delete selected rides");
      const deletedIds = new Set(pendingDeleteIds);
      setRides((current) =>
        current.filter((ride) => !deletedIds.has(ride._id)),
      );
      setTotalCount((current) =>
        Math.max(0, current - pendingDeleteIds.length),
      );
      setSelectedIds((current) => current.filter((id) => !deletedIds.has(id)));
      setPendingDeleteIds(null);
      setPassword("");
      refresh();
    } catch (err) {
      setDeleteError(
        err instanceof Error ? err.message : "Failed to delete selected rides",
      );
    } finally {
      setDeleting(false);
    }
  }

  useEffect(() => {
    let active = true;

    const loadRides = async () => {
      try {
        const params = new URLSearchParams({
          page: String(page),
          limit: String(PAGE_SIZE),
        });
        if (filters.q) {
          params.set("q", filters.q);
          params.set("searchBy", filters.searchBy);
        }
        if (filters.dateFrom) params.set("dateFrom", filters.dateFrom);
        if (filters.dateTo) params.set("dateTo", filters.dateTo);
        if (filters.vehicleType) params.set("vehicleType", filters.vehicleType);
        if (filters.rideType) params.set("rideType", filters.rideType);
        if (filters.status) params.set("status", filters.status);
        if (filters.needsManualAssignment) params.set("needsManualAssignment", "true");

        const res = await fetch(`/api/admin/rides?${params.toString()}`);
        const data = (await res.json().catch(() => null)) as {
          error?: string;
          rides?: RideRow[];
          totalCount?: number;
        } | null;
        if (!res.ok) {
          throw new Error(
            data?.error ?? `Failed to load rides (HTTP ${res.status})`,
          );
        }
        if (!active) return;
        setError(null);
        setRides(data?.rides ?? []);
        setTotalCount(data?.totalCount ?? 0);
        setSelectedIds([]);
      } catch (err) {
        if (!active) return;
        setError(err instanceof Error ? err.message : "Failed to load rides");
        setRides([]);
        setTotalCount(0);
      } finally {
        if (active) setLoading(false);
      }
    };

    void loadRides();
    return () => {
      active = false;
    };
  }, [page, filters, reloadKey]);

  const totalPages = Math.max(1, Math.ceil(totalCount / PAGE_SIZE));
  const visibleIds = useMemo(() => rides.map((ride) => ride._id), [rides]);
  const allVisibleSelected =
    visibleIds.length > 0 && visibleIds.every((id) => selectedIds.includes(id));

  function toggleSelect(id: string) {
    setSelectedIds((current) =>
      current.includes(id)
        ? current.filter((currentId) => currentId !== id)
        : [...current, id],
    );
  }

  function toggleSelectAll() {
    setSelectedIds((current) =>
      allVisibleSelected
        ? current.filter((id) => !visibleIds.includes(id))
        : Array.from(new Set([...current, ...visibleIds])),
    );
  }

  function updateSearchInput(value: string) {
    setSearchInput(value);
    setLoading(true);
    setPage(1);
    setFilters((current) => ({
      ...current,
      q: value.trim(),
      searchBy: searchMode,
    }));
  }

  function updateSearchMode(mode: SearchMode) {
    setSearchMode(mode);
    setLoading(true);
    setPage(1);
    setFilters((current) => ({
      ...current,
      q: searchInput.trim(),
      searchBy: mode,
    }));
  }

  function updateFilter(
    field: "vehicleType" | "rideType" | "status" | "needsManualAssignment",
    value: string | boolean,
  ) {
    setLoading(true);
    setPage(1);
    setFilters((current) => ({ ...current, [field]: value }));
  }

  function applyDateRange(next: { dateFrom: string; dateTo: string }) {
    setRange(next);
    setLoading(true);
    setPage(1);
    setFilters((current) => ({
      ...current,
      dateFrom: next.dateFrom,
      dateTo: next.dateTo,
    }));
  }

  function resetFilters() {
    setLoading(true);
    setPage(1);
    setSearchInput("");
    setSearchMode("rideNumber");
    setRange({ dateFrom: "", dateTo: "" });
    setFilters({
      q: "",
      searchBy: "rideNumber",
      dateFrom: "",
      dateTo: "",
      vehicleType: "",
      rideType: "",
      status: "",
      needsManualAssignment: false,
    });
  }

  function openDetail(id: string) {
    setDetailId(id);
    setDetail(null);
    setDetailError(null);
    setPassengerActionError(null);
    setDetailLoading(true);
  }

  function closeDetail() {
    setDetailId(null);
    setDetail(null);
    setDetailError(null);
  }

  async function markPassengerStatus(
    tripId: string,
    status: "no_show" | "waiting",
  ) {
    if (!detailId) return;
    setPassengerActionTripId(tripId);
    setPassengerActionError(null);
    try {
      const res = await fetch(`/api/admin/rides/${detailId}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ tripId, status }),
