        .filter-field {
          display: flex;
          flex-direction: column;
          gap: 6px;
          min-width: 150px;
        }
        .filter-field span {
          color: var(--slate);
          font-size: 11px;
          font-weight: 600;
          letter-spacing: 0.06em;
          text-transform: uppercase;
        }
        .filter-field input, .filter-field select {
          min-height: 40px;
          border: 1px solid var(--line);
          border-radius: 8px;
          padding: 8px 10px;
          color: var(--ink);
          background: var(--color-panel);
          font: 600 14px inherit;
        }
        .filter-field input:focus, .filter-field select:focus { outline: 2px solid var(--color-secondary-tint); border-color: var(--teal); }

        .rides-board table { width: 100%; border-collapse: collapse; }
        .rides-board thead th {
          text-align: left;
          padding: 12px 16px;
          font-size: 11px;
          font-weight: 600;
          letter-spacing: 0.08em;
          text-transform: uppercase;
          color: var(--slate);
          border-bottom: 1px solid var(--line);
        }
        .rides-board tbody tr {
          border-bottom: 1px solid var(--line);
          transition: background 0.12s ease;
        }
        .rides-board tbody tr:hover { background: var(--color-secondary-tint); }
        .rides-board tbody tr:last-child { border-bottom: none; }
        .rides-board td { padding: 16px; vertical-align: middle; }
        .rides-board input[type="checkbox"] { width: 16px; height: 16px; accent-color: var(--teal-deep); cursor: pointer; }

        .route-line {
          display: flex;
          align-items: center;
          gap: 8px;
          min-width: 220px;
        }
        .route-line .stops {
          display: flex;
          flex-direction: column;
          gap: 3px;
          min-width: 0;
        }
        .route-line .addr {
          font-size: 13px;
          color: var(--ink);
          max-width: 240px;
          overflow: hidden;
          text-overflow: ellipsis;
          white-space: nowrap;
        }
        .status-pill {
          display: inline-block;
          padding: 5px 11px;
          border-radius: 999px;
          font-size: 12px;
          font-weight: 600;
          text-transform: capitalize;
          white-space: nowrap;
        }
        .driver-chip { display: flex; align-items: center; gap: 9px; }
        .driver-chip .avatar {
          width: 28px; height: 28px; border-radius: 50%;
          background: var(--ink);
          color: var(--color-on-primary);
          font-size: 11px;
          font-weight: 600;
          display: flex; align-items: center; justify-content: center;
          flex-shrink: 0;
        }
        .action-btn {
          display: inline-flex; align-items: center; gap: 6px;
          padding: 8px 12px;
          border-radius: 8px;
          font-size: 13px;
          font-weight: 600;
          cursor: pointer;
          border: 1px solid transparent;
          transition: opacity 0.12s ease;
        }
        .action-btn:hover { opacity: 0.75; }
        .action-btn.delete { background: var(--color-danger-tint); color: var(--rose); }
        .action-btn.solid-danger { background: var(--rose); color: var(--color-on-primary); }
        .action-btn.ghost { background: var(--color-panel); color: var(--slate); border-color: var(--line); }
        .rides-board tbody tr.row-link { cursor: pointer; }
        .rides-board tbody tr.row-link:focus-visible { outline: 2px solid var(--teal); outline-offset: -2px; }
        .detail-overlay { position: fixed; inset: 0; z-index: 1200; background: var(--color-overlay); display: flex; justify-content: flex-end; }
        .detail-drawer { width: min(620px, 100%); height: 100dvh; overflow-y: auto; background: var(--color-panel); border-top: 3px solid var(--teal); box-shadow: -12px 0 40px var(--color-shadow-strong); }
        .detail-section { border: 1px solid var(--line); border-radius: 8px; padding: 14px; }
        .detail-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
        .detail-label { display: block; margin-bottom: 3px; color: var(--slate); font-size: 11px; font-weight: 600; letter-spacing: 0.05em; text-transform: uppercase; }
        .route-stop { display: grid; grid-template-columns: 28px minmax(0, 1fr) auto; gap: 10px; align-items: center; padding: 10px 0; border-bottom: 1px solid var(--line); }
        .route-stop:last-child { border-bottom: none; }
        .route-stop-number { display: grid; width: 24px; height: 24px; place-items: center; border-radius: 50%; background: var(--teal); color: var(--color-on-primary); font: 600 11px 'JetBrains Mono', monospace; }
        .route-stop-name { overflow: hidden; color: var(--ink); font-size: 13px; font-weight: 600; text-overflow: ellipsis; white-space: nowrap; }
        .route-stop-meta { color: var(--slate); font-size: 12px; }
        .bulk-bar { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; padding: 12px 20px; background: var(--color-secondary-tint); border-bottom: 1px solid var(--line); }
        .passenger-row { display: grid; grid-template-columns: 34px minmax(0, 1fr) auto; gap: 10px; align-items: center; padding: 10px 0; border-bottom: 1px solid var(--line); }
        .passenger-row:last-child { border-bottom: none; }
        .passenger-avatar { display: grid; width: 32px; height: 32px; place-items: center; border-radius: 50%; background: var(--ink); color: var(--color-on-primary); font-size: 11px; font-weight: 700; overflow: hidden; }
        .passenger-avatar img { width: 100%; height: 100%; object-fit: cover; }
        .avail-option { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 12px; align-items: center; width: 100%; padding: 12px; text-align: left; border: 1px solid var(--line); border-radius: 10px; background: var(--color-panel); cursor: pointer; transition: border-color 0.12s ease, background 0.12s ease; }
        .avail-option:hover:not(:disabled) { border-color: var(--teal); background: var(--color-secondary-tint); }
        .avail-option:disabled { opacity: 0.6; cursor: not-allowed; }
        @media (max-width: 560px) { .detail-grid { grid-template-columns: 1fr; } }
      `}</style>

      <div style={{ maxWidth: 1240, margin: "0 auto" }}>
        <AdminPageHeader
          title="Rides Board"
          description={loading ? "Loading rides board…" : `${totalCount} ride${totalCount === 1 ? "" : "s"} match the current filters · ${rides.length} record${rides.length === 1 ? "" : "s"} on this page`}
          icon={Route}
          actions={
            <>
            <Link href="/admin/trips" className="tab-btn inactive">
              Single Trips
            </Link>
            <Link href="/admin/rides" className="tab-btn active">
              Matched Rides
            </Link>
            </>
          }
        />

        {error ? (
          <p
            role="alert"
            style={{
              marginBottom: 16,
              padding: "12px 14px",
              borderRadius: 10,
              background: "var(--color-danger-tint)",
              color: "var(--color-danger)",
              border: "1px solid var(--color-danger)",
              fontSize: 14,
            }}
          >
            {error}
          </p>
        ) : null}

        {assignError ? (
          <p
            role="alert"
            style={{
              marginBottom: 16,
              padding: "12px 14px",
              borderRadius: 10,
              background: "var(--color-danger-tint)",
              color: "var(--color-danger)",
              border: "1px solid var(--color-danger)",
              fontSize: 14,
            }}
          >
            {assignError}
          </p>
        ) : null}

        <div
          style={{
            display: "flex",
            gap: 12,
            flexWrap: "wrap",
            alignItems: "flex-end",
            background: "var(--color-panel)",
            border: "1px solid var(--color-border)",
            borderRadius: 8,
            padding: 16,
            marginBottom: 16,
          }}
        >
          <label className="filter-field">
            <span>Search by</span>
            <select
              value={searchMode}
              onChange={(event) =>
                updateSearchMode(event.target.value as SearchMode)
              }
            >
              {SEARCH_MODES.map((mode) => (
                <option key={mode.value} value={mode.value}>
                  {mode.label}
                </option>
              ))}
            </select>
          </label>
          <label className="inline-flex items-center gap-2 self-end rounded-lg border border-[var(--color-border)] px-3 py-2 text-xs font-bold text-[var(--color-primary)]">
            <input
              type="checkbox"
              checked={filters.needsManualAssignment}
              onChange={(event) =>
                updateFilter("needsManualAssignment", event.target.checked)
              }
            />
            Needs manual assignment
          </label>
          <label className="filter-field" style={{ flex: "1 1 230px" }}>
            <span>Search value</span>
            <input
              value={searchInput}
              onChange={(event) => updateSearchInput(event.target.value)}
              inputMode="numeric"
              placeholder={
                SEARCH_MODES.find((mode) => mode.value === searchMode)
                  ?.placeholder
              }
            />
          </label>
          <div className="filter-field" style={{ minWidth: 0 }}>
            <span>Ride date</span>
            <AdminDateRangeCalendar
              dateFrom={range.dateFrom}
              dateTo={range.dateTo}
              onApply={applyDateRange}
              align="end"
            />
          </div>
          <label className="filter-field">
            <span>Vehicle</span>
            <select
              value={filters.vehicleType}
              onChange={(event) =>
                updateFilter("vehicleType", event.target.value)
              }
            >
              <option value="">All vehicles</option>
              {Object.entries(VEHICLES).map(([key, vehicle]) => (
                <option key={key} value={key}>
                  {vehicle.label}
                </option>
              ))}
            </select>
          </label>
          <label className="filter-field">
            <span>Status</span>
            <select
              value={filters.status}
              onChange={(event) => updateFilter("status", event.target.value)}
            >
              <option value="">All statuses</option>
              {Object.keys(STATUS_STYLES).map((status) => (
                <option key={status} value={status}>
                  {getStatusStyle(status).label ?? status}
                </option>
              ))}
            </select>
          </label>
          <button
            type="button"
            onClick={resetFilters}
            className="action-btn ghost"
          >
            <RotateCcw size={14} /> Reset
          </button>
        </div>

        <section
          style={{
            borderRadius: 20,
            background: "var(--color-panel)",
            border: "1px solid var(--color-border)",
            boxShadow: "0 10px 35px var(--color-shadow)",
            overflow: "hidden",
          }}
        >
          <div
            style={{
              padding: "18px 24px",
              borderBottom: "1px solid var(--color-border)",
              display: "flex",
              alignItems: "center",
              gap: 12,
              borderTop: "3px solid var(--color-secondary)",
            }}
          >
            <div
              style={{
                width: 40,
                height: 40,
                borderRadius: 10,
                background: "var(--color-secondary-tint)",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              <Route size={18} style={{ color: "var(--color-secondary-deep)" }} />
            </div>
            <div>
              <h2
                className="display"
                style={{
                  margin: 0,
                  fontSize: 16,
                  fontWeight: 700,
                  color: "var(--color-primary)",
                }}
              >
                All Matched Rides
              </h2>
              <p style={{ margin: "3px 0 0", color: "var(--color-muted)", fontSize: 13 }}>
                View and manage multi-passenger matched rides across drivers.
              </p>
            </div>
          </div>

          {selectedIds.length > 0 ? (
            <div className="bulk-bar">
              <span style={{ color: "var(--color-primary)", fontSize: 13, fontWeight: 600 }}>
                {selectedIds.length} ride{selectedIds.length === 1 ? "" : "s"}{" "}
                selected
              </span>
              <div style={{ display: "flex", gap: 8 }}>
                <button
                  type="button"
                  className="action-btn ghost"
                  onClick={() => setSelectedIds([])}
                >
                  Clear selection
                </button>
                <button
                  type="button"
                  className="action-btn solid-danger"
                  onClick={() => {
                    setPendingDeleteIds(selectedIds);
                    setDeleteError(null);
                  }}
                >
                  <Trash2 size={14} /> Delete selected
                </button>
              </div>
            </div>
          ) : null}

          <div className="admin-table-scroll">
            <table>
              <thead>
                <tr>
                  <th style={{ width: 44 }}>
                    <input
                      type="checkbox"
                      aria-label="Select every ride on this page"
                      checked={allVisibleSelected}
                      onChange={toggleSelectAll}
                      disabled={loading || rides.length === 0}
                    />
                  </th>
                  <th>Ride</th>
                  <th>Driver</th>
                  <th>Route (First → Final Station)</th>
                  <th>Date & Time</th>
                  <th>Vehicle / Type</th>
                  <th>Status</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {loading ? (
                  <tr>
                    <td
                      colSpan={8}
                      style={{
                        textAlign: "center",
                        padding: 32,
                        color: "var(--color-muted)",
                      }}
                    >
                      Loading rides...
                    </td>
                  </tr>
                ) : rides.length === 0 ? (
                  <tr>
                    <td
                      colSpan={8}
                      style={{
                        textAlign: "center",
                        padding: 32,
                        color: "var(--color-muted)",
                      }}
                    >
                      No rides matched yet. Go to Admin Dashboard to match trips
                      into a ride.
                    </td>
                  </tr>
                ) : (
                  rides.map((ride) => {
                    const st = getStatusStyle(ride.status);
                    const driverName = ride.driverId?.name ?? "Unassigned";
                    const routeStops = ride.route ?? [];
                    const firstStop =
                      routeStops[0]?.point?.address ??
                      ride.pickupStation?.name ??
                      "First station";
                    const lastStop =
                      routeStops[routeStops.length - 1]?.point?.address ??
                      ride.dropoffStation?.name ??
                      "Final station";
                    const vLabel =
                      VEHICLES[ride.vehicleType as VehicleKey]?.label ??
                      ride.vehicleType;
                    const isSelected = selectedIds.includes(ride._id);

                    return (
                      <tr
                        key={ride._id}
                        className="row-link"
                        tabIndex={0}
                        role="button"
                        aria-label={`Open details for ride ${ride.rideNumber ?? ride._id.slice(-6)}`}
                        onClick={() => openDetail(ride._id)}
                        onKeyDown={(event) => {
                          if (event.key === "Enter" || event.key === " ") {
                            event.preventDefault();
                            openDetail(ride._id);
                          }
                        }}
                      >
                        <td onClick={(event) => event.stopPropagation()}>
                          <input
                            type="checkbox"
                            aria-label={`Select ride ${ride.rideNumber ?? ride._id.slice(-6)}`}
                            checked={isSelected}
                            onChange={() => toggleSelect(ride._id)}
                          />
                        </td>
                        <td>
                          <div>
                            <span
                              className="mono"
                              style={{
                                fontSize: 13,
                                fontWeight: 700,
                                color: "var(--color-primary)",
                              }}
                            >
                              Ride #{ride.rideNumber ?? ride._id.slice(-6)}
                            </span>
                            <span
                              style={{
                                display: "block",
                                fontSize: 11,
                                color: "var(--color-muted)",
                                marginTop: 2,
                              }}
                            >
                              {passengerCount(ride)} passenger
                              {passengerCount(ride) === 1 ? "" : "s"} ·{" "}
                              {ride.totalCost} EGP
                            </span>
                          </div>
                        </td>
                        <td>
                          <div className="driver-chip">
                            <div className="avatar">{initials(driverName)}</div>
                            <div>
                              <span className="name">{driverName}</span>
                              {ride.driverId?.phone && (
                                <span
                                  style={{
                                    display: "block",
                                    fontSize: 11,
                                    color: "var(--color-muted)",
                                  }}
                                >
                                  {ride.driverId.phone}
                                </span>
                              )}
                            </div>
                          </div>
                        </td>
                        <td>
                          <div className="route-line">
                            <div className="stops">
                              <span className="addr" title={firstStop}>
                                1. {firstStop}
                              </span>
                              {routeStops.length > 2 && (
                                <span
                                  style={{
                                    fontSize: 11,
                                    color: "var(--color-secondary-deep)",
                                    fontWeight: 600,
                                    paddingLeft: 12,
                                  }}
                                >
                                  + {routeStops.length - 2} intermediate
                                  station(s)
                                </span>
                              )}
                              <span className="addr" title={lastStop}>
                                {routeStops.length || "N"}. {lastStop}
                              </span>
                            </div>
                          </div>
                        </td>
                        <td>
                          <div>
                            <span
                              style={{
                                fontSize: 13,
                                fontWeight: 600,
                                color: "var(--color-primary)",
                                display: "block",
                              }}
                            >
                              {ride.date}
                            </span>
                            <span
                              className="mono"
                              style={{ fontSize: 12, color: "var(--color-muted)" }}
                            >
                              {to12h(ride.startTime)} – {to12h(ride.endTime)}
                            </span>
                          </div>
                        </td>
                        <td>
                          <div>
                            <span
                              style={{
                                fontSize: 13,
                                fontWeight: 600,
                                color: "var(--color-primary)",
                              }}
                            >
                              {vLabel}
                            </span>
                            <span
                              style={{
                                display: "block",
                                fontSize: 11,
                                color: "var(--color-muted)",
                                textTransform: "capitalize",
                              }}
                            >
                              {ride.rideType} ride
                            </span>
                          </div>
                        </td>
                        <td>
                          <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
                            <span
                              className="status-pill"
                              style={{ background: st.bg, color: st.color }}
                            >
                              {st.label ?? ride.status}
                            </span>
                            {ride.needsManualAssignment ? (
                              <span
                                className="status-pill"
                                style={{ background: "var(--color-danger-tint)", color: "var(--color-danger)" }}
                              >
                                No driver accepted
                              </span>
                            ) : null}
                          </div>
                        </td>
                        <td onClick={(event) => event.stopPropagation()}>
                          <div
                            style={{
                              display: "flex",
                              gap: 8,
                              flexWrap: "wrap",
                              alignItems: "center",
                            }}
                          >
                            {!ride.driverId && ride.status !== "completed" && ride.status !== "cancelled" ? (
                              <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
                                <select
                                  value={assignDriverByRide[ride._id] ?? ""}
                                  onChange={(event) =>
                                    setAssignDriverByRide((current) => ({
                                      ...current,
                                      [ride._id]: event.target.value,
                                    }))
                                  }
                                  style={{
                                    fontSize: 12,
                                    padding: "6px 8px",
                                    borderRadius: 8,
                                    border: "1px solid var(--color-border)",
                                    maxWidth: 160,
                                  }}
                                >
                                  <option value="">Assign driver…</option>
                                  {drivers
                                    .filter((driver) => driver.verificationStatus === "verified")
                                    .map((driver) => (
                                      <option key={driver._id} value={driver._id}>
                                        {driver.name} {driver.phone ? `· ${driver.phone}` : ""}
                                      </option>
                                    ))}
                                </select>
                                <button
                                  type="button"
                                  className="action-btn"
                                  onClick={() => assignDriver(ride._id)}
                                  disabled={assigningRideId === ride._id}
                                  title="Force-assign this driver to the ride"
                                >
                                  {assigningRideId === ride._id ? "Assigning…" : "Assign"}
                                </button>
                              </div>
                            ) : null}
                            <button
                              type="button"
                              className="action-btn delete"
                              onClick={() => deleteRide(ride._id)}
                              title={
                                ride.status === "completed"
                                  ? "Cannot delete a completed ride"
                                  : "Permanently delete ride and restore trips"
                              }
                              disabled={ride.status === "completed"}
                              style={
                                ride.status === "completed"
                                  ? { opacity: 0.45, cursor: "not-allowed" }
                                  : undefined
                              }
                            >
                              <Trash2 size={14} /> Delete
                            </button>
                          </div>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>
          <div
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              gap: 12,
              flexWrap: "wrap",
              padding: "14px 20px",
              borderTop: "1px solid var(--color-border)",
            }}
          >
            <span style={{ fontSize: 13, color: "var(--color-muted)" }}>
              Page {page} of {totalPages}
            </span>
            <div style={{ display: "flex", gap: 8 }}>
              <button
                type="button"
                className="action-btn ghost"
                disabled={loading || page <= 1}
                onClick={() => {
                  setLoading(true);
                  setPage((current) => Math.max(1, current - 1));
                }}
              >
                <ChevronLeft size={14} /> Previous
              </button>
              <button
                type="button"
                className="action-btn ghost"
                disabled={loading || page >= totalPages}
                onClick={() => {
                  setLoading(true);
                  setPage((current) => Math.min(totalPages, current + 1));
                }}
              >
                Next <ChevronRight size={14} />
              </button>
            </div>
          </div>
        </section>
      </div>

      {detailId ? (
        <div
          className="detail-overlay"
          onClick={(event) => {
            if (event.target === event.currentTarget) closeDetail();
          }}
        >
          <aside
            className="detail-drawer"
            role="dialog"
            aria-modal="true"
            aria-label="Ride details"
          >
            <header
              style={{
                display: "flex",
                alignItems: "flex-start",
                justifyContent: "space-between",
                gap: 12,
                padding: "20px 24px",
                borderBottom: "1px solid var(--color-border)",
              }}
            >
              <div>
                <p
                  className="mono"
                  style={{
                    margin: 0,
                    fontSize: 11,
                    fontWeight: 600,
                    letterSpacing: "0.14em",
                    textTransform: "uppercase",
                    color: "var(--color-secondary-deep)",
                  }}
                >
                  Ride details
                </p>
                <h3
                  className="display"
                  style={{
                    margin: "5px 0 0",
                    fontSize: 20,
                    fontWeight: 700,
                    color: "var(--color-primary)",
                  }}
                >
                  {detail
                    ? `Ride #${detail.rideNumber ?? detail._id.slice(-6)}`
                    : "Loading..."}
                </h3>
                {detail ? (
                  <p
                    style={{
                      margin: "4px 0 0",
                      color: "var(--color-muted)",
                      fontSize: 13,
                    }}
                  >
                    {detail.date} · {to12h(detail.startTime)} -{" "}
                    {to12h(detail.endTime)}
                  </p>
                ) : null}
              </div>
              <button
                type="button"
                onClick={closeDetail}
                aria-label="Close details"
                style={{
                  padding: 4,
                  color: "var(--color-muted)",
                  background: "transparent",
                  border: "none",
                  cursor: "pointer",
                }}
              >
                <X size={20} />
              </button>
            </header>

            <div
              style={{
                display: "flex",
                flexDirection: "column",
                gap: 14,
                padding: 20,
              }}
            >
              {detailLoading ? (
                <p style={{ margin: 0, color: "var(--color-muted)", fontSize: 14 }}>
                  Loading ride details...
                </p>
              ) : detailError ? (
                <p
                  role="alert"
                  style={{
                    margin: 0,
                    padding: "12px 14px",
                    borderRadius: 8,
                    background: "var(--color-danger-tint)",
                    color: "var(--color-danger)",
