  "rideId",
  "passId",
  "originNearestStationNo",
  "originLat",
  "originLong",
  "destinationNearestStationNo",
  "destinationLat",
  "destinationLong",
  "stop1Lat",
  "stop1Long",
  "stop1Alighting",
  "stop1Boarding",
  "stop1WaitingTime",
  "stop2Lat",
  "stop2Long",
  "stop2Alighting",
  "stop2Boarding",
  "stop2WaitingTime",
