import { connectDB } from "@/lib/db/mongoose";
import { WithdrawalRequest } from "@/models/WithdrawalRequest";
import { Wallet } from "@/models/Wallet";
import { User } from "@/models/User";
import { getAdminSettings, computeWithdrawableBalance } from "@/lib/cancellationPolicy";

export async function GET(req: NextRequest) {
  const session = await getSession();
  if (!session || session.role !== "admin") {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const { searchParams } = new URL(req.url);
  const statusFilter = searchParams.get("status"); // "pending", "approved", "rejected", "cancelled", or empty for all

  await connectDB();
  const settings = await getAdminSettings();

  const query: Record<string, unknown> = {};
  if (statusFilter && ["pending", "approved", "rejected", "cancelled"].includes(statusFilter)) {
    query.status = statusFilter;
  }

  const requests = await WithdrawalRequest.find(query)
    .sort({ createdAt: -1 })
    .lean();

  const driverIds = Array.from(new Set(requests.map((r) => String(r.driverId))));

  const [users, wallets] = await Promise.all([
    User.find({ _id: { $in: driverIds } }).select("name email phone").lean(),
    Wallet.find({ userId: { $in: driverIds } }).lean(),
  ]);

  const userMap = new Map(users.map((u) => [String(u._id), u]));
  const walletMap = new Map(wallets.map((w) => [String(w.userId), w]));

  const data = requests.map((r: any) => {
    const driver = userMap.get(String(r.driverId));
    const wallet = walletMap.get(String(r.driverId));

    const balanceEgp = wallet?.balanceEgp ?? 0;
    const reserveAmount = wallet?.reserveAmount ?? settings.walletReserveAmount ?? 200;
    const pendingWithdrawalAmount = wallet?.pendingWithdrawalAmount ?? 0;
    const withdrawableEgp = computeWithdrawableBalance(
      balanceEgp,
      reserveAmount,
      pendingWithdrawalAmount,
    );

    return {
      id: String(r._id),
      driverId: String(r.driverId),
      driverName: driver?.name ?? "Unknown Driver",
      driverEmail: driver?.email ?? "",
      driverPhone: driver?.phone ?? "",
      amountEgp: r.amountEgp,
      status: r.status,
      payoutMethod: r.payoutMethod,
      payoutDestination: r.payoutDestination,
      rejectionReason: r.rejectionReason ?? null,
      requestedAt: r.requestedAt ? new Date(r.requestedAt).toISOString() : String(r.createdAt),
      resolvedAt: r.resolvedAt ? new Date(r.resolvedAt).toISOString() : null,
      wallet: {
        balanceEgp,
        reserveAmount,
        pendingWithdrawalAmount,
        withdrawableEgp,
        withdrawalLimit: wallet?.withdrawalLimit ?? settings.defaultWithdrawalLimit ?? null,
      },
    };
  });

  return NextResponse.json({ requests: data });
}

import { NextRequest, NextResponse } from "next/server";

const ORS_URL =
  "https://api.openrouteservice.org/v2/directions/driving-car/geojson";

export async function POST(req: NextRequest) {
  const apiKey = process.env.ORS_API_KEY ?? process.env.NEXT_PUBLIC_ORS_API_KEY;
  if (!apiKey) {
    return NextResponse.json({ error: "ORS API key not configured" }, { status: 500 });
  }

  let body: any;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  // Try a couple of times for transient upstream failures (504, 502)
  const attempts = 2;
  for (let i = 0; i < attempts; i++) {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 10_000);
    try {
      const res = await fetch(ORS_URL, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: apiKey,
        },
        body: JSON.stringify(body),
        signal: controller.signal,
      });

      clearTimeout(timeout);
      const text = await res.text();
      const contentType = res.headers.get("content-type") || "";

      if (!res.ok) {
        console.error(`/api/ors error (attempt ${i + 1})`, res.status, text.slice(0, 200));
        // Retry on server errors
        if (res.status >= 500 && i + 1 < attempts) {
          await new Promise(r => setTimeout(r, 500 * (i + 1)));
          continue;
        }
        return NextResponse.json({ error: "ORS request failed", details: text }, { status: 502 });
      }

      // Return raw ORS response with correct content-type
      if (contentType.includes("json") || contentType.includes("geo+json")) {
        try {
          return NextResponse.json(JSON.parse(text));
        } catch {
          return new NextResponse(text, { status: 200, headers: { "Content-Type": contentType } });
        }
      }

      return new NextResponse(text, { status: 200, headers: { "Content-Type": contentType } });
    } catch (err) {
      clearTimeout(timeout);
      console.error(`/api/ors fetch attempt ${i + 1} failed:`, err);
      if (i + 1 < attempts) {
        await new Promise(r => setTimeout(r, 500 * (i + 1)));
        continue;
      }
      return NextResponse.json({ error: "Network error contacting ORS" }, { status: 502 });
    }
  }

  return NextResponse.json({ error: "ORS request failed after retries" }, { status: 502 });
}

import { NextRequest, NextResponse } from "next/server";
import { connectDB } from "@/lib/db/mongoose";
import {
  updatePassengerStatusInRide,
  removePassengerFromRide,
} from "@/lib/services/rideService";

// PATCH /api/rides/:id/passengers/:tripId — update one passenger's status
export async function PATCH(
  req: NextRequest,
  { params }: { params: any },
) {
  try {
    await connectDB();
    const { status } = await req.json();
    if (!status) {
      return NextResponse.json(
        { error: "status is required" },
        { status: 400 },
      );
    }
    const ride = await updatePassengerStatusInRide(
      params.id,
      params.tripId,
      status,
    );
    if (!ride) {
      return NextResponse.json(
        { error: "Ride or passenger not found" },
        { status: 404 },
      );
    }
    return NextResponse.json({ data: ride });
  } catch (err: any) {
    return NextResponse.json(
      { error: err.message || "Failed to update passenger status" },
      { status: 400 },
    );
  }
}

// DELETE /api/rides/:id/passengers/:tripId — remove a passenger from the ride
export async function DELETE(
  req: NextRequest,
  { params }: { params: any },
) {
  try {
    await connectDB();
    const { reason } = await req.json().catch(() => ({ reason: undefined }));
    const ride = await removePassengerFromRide(
      params.id,
      params.tripId,
      reason,
    );
    return NextResponse.json({ data: ride });
  } catch (err: any) {
    return NextResponse.json(
      { error: err.message || "Failed to remove passenger" },
      { status: 400 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { connectDB } from "@/lib/db/mongoose";
