  cancelRideByDriver,
} from "@/lib/services/rideService";

// GET /api/rides/:id
export async function GET(_req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  try {
    const { id } = await params;
    await connectDB();
    const ride = await getRideById(id);
    if (!ride) {
      return NextResponse.json({ error: "Ride not found" }, { status: 404 });
    }
    return NextResponse.json({ data: ride });
  } catch (err: any) {
    return NextResponse.json(
      { error: err.message || "Failed to fetch ride" },
      { status: 500 },
    );
  }
}

// PATCH /api/rides/:id — update ride status (confirmed/active/completed)
export async function PATCH(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  try {
    const { id } = await params;
    await connectDB();
    const { status } = await req.json();
    if (!status) {
      return NextResponse.json(
        { error: "status is required" },
        { status: 400 },
      );
    }
    const ride = await updateRideStatus(id, status);
    if (!ride) {
      return NextResponse.json({ error: "Ride not found" }, { status: 404 });
    }
    return NextResponse.json({ data: ride });
  } catch (err: any) {
    return NextResponse.json(
      { error: err.message || "Failed to update ride" },
      { status: 400 },
    );
  }
}

// DELETE /api/rides/:id — cancel (never hard delete)
export async function DELETE(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  try {
    const { id } = await params;
    await connectDB();
    const session = await getSession();
    const { reason } = await req.json().catch(() => ({ reason: undefined }));

    let ride;
    if (session?.role === "driver") {
      ride = await cancelRideByDriver(id, session.userId, reason);
    } else {
      ride = await cancelRide(id, reason);
    }

    return NextResponse.json({ data: ride });
  } catch (err: any) {
    return NextResponse.json(
      { error: err.message || "Failed to cancel ride" },
      { status: 400 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { connectDB } from "@/lib/db/mongoose";
import {
  createRide,
  getRidesByDriver,
  getRideByPassengerIncluded,
} from "@/lib/services/rideService";

export async function POST(req: NextRequest) {
  try {
    await connectDB();
    const body = await req.json();
    const ride = await createRide(body);
    return NextResponse.json({ data: ride }, { status: 201 });
  } catch (err: any) {
    return NextResponse.json(
      { error: err.message || "Failed to create ride" },
      { status: 400 },
    );
  }
}

export async function GET(req: NextRequest) {
  try {
    await connectDB();
    const { searchParams } = new URL(req.url);
    const driverId = searchParams.get("driverId");
    const passengerId = searchParams.get("passengerId");
    const date = searchParams.get("date") ?? undefined;
    if (passengerId) {
      const rides = await getRideByPassengerIncluded(passengerId);
      return NextResponse.json({ data: rides });
    }

    if (!driverId) {
      return NextResponse.json({ error: "driverId is required" }, { status: 400 });
    }
    const rides = await getRidesByDriver(driverId, date);
    return NextResponse.json({ data: rides });
  } catch (err: any) {
    return NextResponse.json(
      { error: err.message || "Failed to fetch rides" },
      { status: 500 },
    );
  }
}

