function TripActions({
  trip,
  displayStatus,
  walletBalance,
  isDriver,
}: {
  trip: UserTripDetail;
  displayStatus: ReturnType<typeof getDisplayStatus>;
  walletBalance: number;
  isDriver: boolean;
}) {
  if (isDriver) return null;
  if (trip.isStandalone) {
    return (
      <div style={{ display: "grid", gap: 8 }}>
        {displayStatus.canPay && (
          <ContinueCheckoutButton
            bookingId={trip.id}
            amountEgp={trip.priceEgp}
            walletBalance={walletBalance}
          />
        )}
        {displayStatus.canCancel && (
          <CancelTripModal
            tripId={trip.id}
            tripNumber={trip.tripNumber}
            date={trip.date}
            priceEgp={trip.priceEgp}
            status={trip.status}
            isStandalone
            paymentStatus={trip.paymentStatus}
          />
        )}
        {displayStatus.canRate && (
          <RateTripModal tripId={trip.id} initialRating={trip.rating ?? null} />
        )}
      </div>
    );
  }
  if (displayStatus.canPay) {
    return (
      <ContinueCheckoutButton
        bookingId={trip.isStandalone ? trip.id : trip.requestId}
        amountEgp={
          trip.isStandalone
            ? trip.priceEgp
            : trip.requestAmountEgp ?? trip.priceEgp
        }
        walletBalance={walletBalance}
      />
    );
  }
  if (displayStatus.canCancel) {
    return (
      <CancelTripModal
        tripId={trip.id}
        tripNumber={trip.tripNumber}
        date={trip.date}
        priceEgp={trip.priceEgp}
        status={trip.status}
        isStandalone={false}
        paymentStatus={trip.paymentStatus}
      />
    );
  }
  if (displayStatus.canRate) {
    return <RateTripModal tripId={trip.id} initialRating={trip.rating ?? null} />;
  }
  return null;
}

