          .my-trips-sidebar-panel:last-child {
            margin-bottom: 0;
          }
          .my-trips-sidebar-label {
            font-size: 11px;
            font-weight: 800;
            color: #5A6A7A;
            text-transform: uppercase;
            letter-spacing: 0.06em;
            margin: 0 0 var(--space-12);
