          .my-trips-stat-row {
            display: flex;
            align-items: baseline;
            justify-content: space-between;
            gap: var(--space-8);
            padding: var(--space-8) 0;
            border-bottom: 1px solid #f4f6f8;
          }
          .my-trips-stat-row:last-child {
            border-bottom: none;
            padding-bottom: 0;
          }
          .my-trips-stat-row:first-of-type {
            padding-top: 0;
          }
        }
      `}</style>

      <main className="my-trips-shell">
