              </div>
              {(dateFrom || dateTo) && (
                <div className="my-trips-stat-row">
                  <span style={{ fontSize: 13, color: "#5A6A7A" }}>
                    {translate(locale, "my_trips.date_filter_label")}
                  </span>
                  <span style={{ fontSize: 13, fontWeight: 700, color: "#0B1E3D" }}>
