                                        background:
                                          ride.rideType === "shared"
                                            ? "#E8F8F5"
                                            : "#EEF2FF",
                                        color:
                                          ride.rideType === "shared"
                                            ? "#00806E"
                                            : "#0B1E3D",
                                        textTransform: "capitalize",
