                                  <Pill {...rideStatusPill(ride.status, locale)} />
                                  <span
                                    style={{
                                      display: "inline-flex",
                                      alignItems: "center",
                                      gap: 4,
                                      fontSize: 12,
                                      color: "#5A6A7A",
