                                  >
                                    <Users size={12} aria-hidden="true" />
                                    {ride.passengerCount} {ride.passengerCount === 1 ? translate(locale, "my_trips.passenger_singular") : translate(locale, "my_trips.passenger_plural")}
                                  </span>
