                                                ? (passenger.dropoffStation?.name ??
                                                  ride.dropoffStation?.name ??
                                                  passenger.dropoffAddress)
                                                : passenger.dropoffAddress
                                            }
                                            style={{
                                              fontSize: 13,
                                              color: "#0B1E3D",
                                            }}
                                          >
                                            {truncate(
                                              ride.rideType === "shared"
                                                ? (passenger.dropoffStation?.name ??
                                                  ride.dropoffStation?.name ??
                                                  passenger.dropoffAddress)
                                                : passenger.dropoffAddress,
                                            )}
                                          </span>
                                        </div>
