                      paymentStatus: trip.isStandalone
                        ? trip.paymentStatus
                        : trip.parentPaymentStatus ?? trip.paymentStatus,
                      hasPastTrip: trip.hasPastTrip,
                      rejectionReason: trip.rejectionReason,
                    };
