                            display: "block",
                          }}
                        >
                          <div style={{ padding: "16px 18px" }}>
                            <div style={{ marginBottom: 10 }}>
                              <span
                                style={{
                                  fontSize: 11,
                                  color: "#9aa7b4",
                                  fontWeight: 600,
                                }}
                              >
                                {translate(locale, "my_trips.trip_number", { n: trip.tripNumber })} · {translate(locale, "my_trips.requested_label")} {" "}
                                {toArabicDigitsIf(locale, new Date(trip.createdAt).toLocaleString(locale === "ar" ? "ar-EG" : "en-EG", {
                                  month: "short",
                                  day: "numeric",
                                  hour: "numeric",
                                  minute: "2-digit",
                                }))}
                              </span>
                            </div>

                            <div
                              style={{
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "space-between",
                                gap: 8,
                                marginBottom: 8,
                              }}
                            >
                              <div style={{ display: "flex", alignItems: "center", gap: 8, minWidth: 0, flexWrap: "wrap" }}>
                                <Car size={20} color="#00806E" aria-hidden="true" />
                                <span style={{ fontSize: 16, fontWeight: 800, color: "#0B1E3D" }}>
                                  {vLabel}
                                </span>
                                <span className="trip-type-badge">
                                  {translate(locale, sharedTrip ? "ride.shared" : "ride.private")}
                                </span>
                              </div>
                              <span style={{ fontWeight: 800, fontSize: 16, color: "#00C2A8", fontVariantNumeric: "tabular-nums" }}>
                                {formatEgp(locale, trip.priceEgp)}
                              </span>
                            </div>

                            <div
                              style={{
                                display: "flex",
                                justifyContent: "space-between",
                                gap: 8,
                                marginBottom: 12,
                                fontSize: 12,
                                color: "#5A6A7A",
                              }}
                            >
                              <span>{translate(locale, "my_trips.trip_fare")}</span>
                              <span style={{ fontWeight: 700, color: "#0B1E3D", fontVariantNumeric: "tabular-nums" }}>
                                {translate(locale, "my_trips.request_total")}: {formatEgp(locale, trip.bookingAmountEgp)}
                              </span>
                            </div>

                            <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", marginBottom: 12 }}>
                              <span className="trip-card-date">
                                {formatDate(locale, trip.date)}
                                <span>{formatTime(locale, trip.pickupTime)}</span>
                              </span>
                              <Pill {...displayPill(locale, displayStatus)} />
                              {trip.status === "matched" && (
                                <MatchedTripCountdown
                                  date={trip.date}
                                  pickupTime={trip.pickupTime}
                                  locale={locale}
                                />
                              )}
                              {displayStatus.showRefundBadge && trip.cancellation && (
                                <span
                                  style={{
                                    display: "inline-flex",
                                    alignItems: "center",
                                    gap: 4,
                                    padding: "3px 10px",
                                    borderRadius: 20,
                                    fontSize: 11,
                                    fontWeight: 700,
                                    background:
                                      trip.cancellation.refundStatus === "approved"
                                        ? "#E8F8F5"
                                        : trip.cancellation.refundStatus === "rejected"
                                          ? "#FDECEA"
                                          : "#FFF3E0",
                                    color:
                                      trip.cancellation.refundStatus === "approved"
                                        ? "#00806E"
                                        : trip.cancellation.refundStatus === "rejected"
                                          ? "#C0392B"
                                          : "#E65100",
                                    border: `1px solid ${
                                      trip.cancellation.refundStatus === "approved"
                                        ? "#CBE9E2"
                                        : trip.cancellation.refundStatus === "rejected"
                                          ? "#FADBD8"
                                          : "#FFE0B2"
                                    }`,
                                  }}
                                >
                                  {trip.cancellation.refundStatus === "approved"
                                    ? `Refund Approved (${trip.cancellation.refundAmount} EGP)`
                                    : trip.cancellation.refundStatus === "rejected"
                                      ? "Refund Rejected"
                                      : `Refund Pending Review (${trip.cancellation.refundAmount} EGP)`}
                                </span>
                              )}
                            </div>
                            {(rejectionDisplay.showReasonCard || displayStatus.secondaryKey || displayStatus.secondaryText) && (
                              <p
                                className={displayStatus.secondaryKey === "status.approved_by_admin" ? "trip-approved-caption" : undefined}
                                title={rejectionDisplay.showReasonCard ? (rejectionDisplay.reason ?? translate(locale, "rejection.no_reason")) : undefined}
                                style={{
                                  margin: displayStatus.secondaryKey === "status.approved_by_admin" ? "-5px 0 10px" : "-4px 0 12px",
                                  marginInlineStart: displayStatus.secondaryKey === "status.approved_by_admin" ? 28 : 0,
                                  fontSize: displayStatus.secondaryKey === "status.approved_by_admin" ? 11 : 13,
                                  lineHeight: displayStatus.secondaryKey === "status.approved_by_admin" ? 1.35 : 1.5,
                                  color: displayStatus.secondaryKey === "status.approved_by_admin" ? "#687978" : "#5A6A7A",
                                  ...(rejectionDisplay.showReasonCard
                                    ? { overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" as const }
                                    : {}),
                                }}
                              >
                                {rejectionDisplay.showReasonCard
                                  ? rejectionDisplay.reason ?? translate(locale, "rejection.no_reason")
                                  : displayStatus.secondaryKey
                                    ? translate(locale, displayStatus.secondaryKey)
                                    : displayStatus.secondaryText}
                              </p>
                            )}

                            {showSharedSummary ? (
                              <div style={{ marginBottom: 12 }}>
                                <SharedSummaryCard
                                  locale={locale}
                                  driver={sharedDetail?.assignedDriver ?? trip.assignedDriver}
                                  totalPersons={sharedDetail?.rideDetails?.passengerCount ?? sharedDetail?.numberOfPassengers ?? 1}
                                  totalFees={sharedDetail?.rideDetails?.totalCost ?? trip.bookingAmountEgp}
                                  pickupPoint={sharedDetail?.pickupStation?.name ?? trip.pickupAddress}
                                  departureTime={trip.pickupTime}
                                  dropoffPoint={sharedDetail?.dropoffStation?.name ?? trip.dropoffAddress}
                                  arrivalTime={trip.arrivalTime}
                                />
                              </div>
                            ) : (
                              <>
                                {!isDriver && hasAssignedDriver && (
                                  <div style={{ marginBottom: 12, background: "linear-gradient(135deg, #F6FBFA 0%, #EEFBF8 100%)", border: "1px solid #D6F5EE", borderRadius: 14, overflow: "hidden" }}>
                                    <div style={{ display: "flex", alignItems: "center", gap: 12, padding: "12px 14px" }}>
                                      {(trip.assignedDriver?.profilePicture ?? trip.assignedDriver?.profilePic) ? (
                                        // eslint-disable-next-line @next/next/no-img-element
                                        <img
                                          src={trip.assignedDriver.profilePicture ?? trip.assignedDriver.profilePic ?? ""}
                                          alt={trip.assignedDriver?.name ?? translate(locale, "my_trips.driver_fallback")}
                                          style={{ width: 40, height: 40, borderRadius: "50%", objectFit: "cover", flexShrink: 0 }}
                                        />
                                      ) : (
                                        <div style={{ width: 40, height: 40, borderRadius: "50%", flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center", background: "#0B1E3D", color: "#fff", fontWeight: 800, fontSize: 15 }} aria-hidden="true">
                                          {(trip.assignedDriver?.name ?? "").split(" ").filter(Boolean).slice(0, 2).map((p) => p[0]?.toUpperCase()).join("")}
                                        </div>
                                      )}
                                      <div style={{ minWidth: 0, flex: 1 }}>
                                        <p style={{ margin: 0, fontSize: 10, fontWeight: 700, color: "#00806E", textTransform: "uppercase", letterSpacing: "0.05em" }}>
                                          {translate(locale, "my_trips.driver_heading")}
                                        </p>
                                        <p style={{ margin: "1px 0 0", fontSize: 14, fontWeight: 700, color: "#0B1E3D" }}>
                                          {trip.assignedDriver?.name ?? "—"}
                                        </p>
                                      </div>
                                    </div>
                                    <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 14px", borderTop: "1px solid #D6F5EE", background: "rgba(255,255,255,0.5)" }}>
                                      <Car size={16} color="#00806E" style={{ flexShrink: 0 }} aria-hidden="true" />
                                      <span style={{ fontSize: 13, fontWeight: 600, color: "#0B1E3D" }}>
                                        {trip.assignedDriver?.carBrand ?? ""}
                                        {trip.assignedDriver?.carBrand && trip.assignedDriver?.carModel ? " " : ""}
                                        {trip.assignedDriver?.carModel ?? ""}
                                        {trip.assignedDriver?.modelYear ? ` · ${trip.assignedDriver.modelYear}` : ""}
                                      </span>
                                      <span style={{ marginLeft: "auto", display: "inline-flex", alignItems: "center", gap: 6, padding: "4px 10px", borderRadius: 8, background: "#fff", border: "1px solid #CBE9E2", fontSize: 12, fontWeight: 700, color: "#0B1E3D", whiteSpace: "nowrap" }}>
                                        <span style={{ fontSize: 10, color: "#5A6A7A", textTransform: "uppercase", letterSpacing: "0.04em" }}>Color</span>
                                        <span>{trip.assignedDriver?.vehicleColor ?? trip.assignedDriver?.carColor ?? "—"}</span>
                                      </span>
                                    </div>
                                  </div>
                                )}

                                <div className="trip-card-route">
                                  <div className="trip-card-route-row">
                                    <MapPin size={13} color="#00C2A8" style={{ marginTop: 2, flexShrink: 0 }} aria-hidden="true" />
                                    <span title={pickupName}>{truncate(pickupName)}</span>
                                  </div>
                                  <div className="trip-card-route-row">
                                    <MapPin size={13} color="#E74C3C" style={{ marginTop: 2, flexShrink: 0 }} aria-hidden="true" />
                                    <span title={dropoffName}>{truncate(dropoffName)}</span>
                                  </div>
                                </div>

                                <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 10, flexWrap: "wrap" }}>
                                  <div style={{ display: "flex", alignItems: "center", gap: 5 }}>
                                    <Clock size={12} color="#5A6A7A" aria-hidden="true" />
                                    <span style={{ fontSize: 12, color: "#5A6A7A" }}>
                                      {isSharedVehicle(trip.vehicleType) ? translate(locale, "board_station_by") : translate(locale, "pickup")} <strong style={{ color: "#0B1E3D" }}>{formatTime(locale, trip.pickupTime)}</strong>
                                    </span>
                                  </div>
                                  <div style={{ display: "flex", alignItems: "center", gap: 5 }}>
                                    <Clock size={12} color="#5A6A7A" aria-hidden="true" />
                                    <span style={{ fontSize: 12, color: "#5A6A7A" }}>
                                      {translate(locale, "arrive")} <strong style={{ color: "#0B1E3D" }}>{formatTime(locale, trip.arrivalTime)}</strong>
                                    </span>
                                  </div>
                                </div>

                                <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
                                  <span style={{ display: "inline-flex", alignItems: "center", gap: 5, fontSize: 12, color: "#647575" }}>
                                    <Route size={12} aria-hidden="true" />
                                    {formatDistanceKm(locale, trip.distanceKm ?? 0)} · {formatMinutes(locale, trip.durationMinutes ?? 0)}
                                  </span>
                                  <span className="trip-card-view-action">
                                    {translate(locale, "my_trips.view_trip")}
                                    <ChevronRight className="rtl-directional-icon" size={15} aria-hidden="true" />
                                  </span>
                                </div>
                              </>
                            )}
                          </div>
                        </Link>
                        {!isDriver && displayStatus.canCancel && (
                          <div style={{ padding: "0 18px 16px", display: "flex", justifyContent: "flex-end" }}>
                            <CancelTripModal
                              tripId={trip.id}
                              tripNumber={trip.tripNumber}
                              date={trip.date}
                              priceEgp={trip.priceEgp}
                              status={trip.status}
                              isStandalone={trip.isStandalone}
                              paymentStatus={trip.paymentStatus}
                            />
                          </div>
                        )}
                        {!isDriver && needsPayment && (
                          <div style={{ padding: "0 18px 16px" }}>
                            <ContinueCheckoutButton
                              bookingId={
                                trip.isStandalone ? trip.id : trip.requestId
                              }
                              amountEgp={
                                trip.isStandalone
                                  ? trip.priceEgp
                                  : trip.bookingAmountEgp
                              }
                              walletBalance={walletBalance}
                            />
                          </div>
                        )}
                        {!isDriver && displayStatus.canRate && (
                          <div style={{ padding: "0 18px 16px" }}>
                            <RateTripModal tripId={trip.id} initialRating={trip.rating ?? null} />
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              </div>
            ))}

            <Pagination page={page} totalPages={totalPages} />
          </>
        )}
          </div>
        </div>
      </main>
    </div>
  );
}

"use client";
import { useState } from "react";
import Link from "next/link";
import {
  User,
  Loader2,
  Check,
  ArrowRight,
  ArrowLeft,
  ShieldCheck,
} from "lucide-react";
import AppHeader from "@/components/layout/AppHeader";
import Section from "@/components/shared/Section";
import ChangePasswordSection from "@/components/shared/ChangePasswordSection";
import PhoneVerificationCard from "@/components/shared/PhoneVerificationCard";
import SecurityQuestionSetupCard from "@/components/shared/SecurityQuestionSetupCard";
import ReferralCard from "@/components/shared/ReferralCard";
import SavedAddressesSection from "@/components/shared/SavedAddressesSection";
import type { CarType } from "@/lib/config/driver";
import type { SavedAddress } from "@/types/shared";
import { useClientLocale } from "@/lib/locale.client";

interface Props {
  userNumber: number;
  initialName: string;
  email: string;
  initialPhone: string;
  initialPhoneVerified: boolean;
  initialHasSecurityQuestion: boolean;
  gender: "male" | "female";
  carType: CarType | "";
  carBrand?: string;
  carModel?: string;
  modelYear?: number | null;
  vehicleColor?: string;
  plateChar1?: string;
  plateChar2?: string;
  plateChar3?: string;
  plateDigits?: string;
  licenseExpiry?: string;
  carCapacity?: number;
  documents: Record<string, string | null>;
  verificationStatus: "incomplete" | "pending" | "verified";
  profileSince: string;
  initialSavedAddresses: SavedAddress[];
}

const labelStyle: React.CSSProperties = {
  fontSize: 13,
  fontWeight: 600,
  color: "#0B1E3D",
  display: "block",
  marginBottom: 6,
};

const inputStyle: React.CSSProperties = {
  width: "100%",
  minWidth: 0,
  height: 48,
  padding: "0 14px",
  background: "#f8f9fa",
  border: "1.5px solid #e8edf0",
  borderRadius: 10,
  fontSize: 14,
  fontFamily: "inherit",
  color: "#0B1E3D",
  outline: "none",
  boxSizing: "border-box",
};

function getSelectStyle(dir: "ltr" | "rtl"): React.CSSProperties {
  const isRtl = dir === "rtl";
  // single-path SVG caret (down arrow) encoded to avoid gradient artifacts near rounded corners
  const encodedSvg = "%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 10 10'%3E%3Cpath d='M1 3l4 4 4-4' stroke='%235A6A7A' stroke-width='1.5' fill='none' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E";

  return {
    ...inputStyle,
    cursor: "pointer",
    paddingInlineEnd: isRtl ? 14 : 36,
    paddingInlineStart: isRtl ? 36 : 14,
    textAlign: isRtl ? "right" : "left",
    appearance: "none",
    WebkitAppearance: "none",
    MozAppearance: "none",
    backgroundImage: `url("data:image/svg+xml;utf8,${encodedSvg}")`,
    backgroundPosition: isRtl ? "12px center" : "calc(100% - 18px) center",
    backgroundSize: "12px",
    backgroundRepeat: "no-repeat",
  };
}

const cardStyle: React.CSSProperties = {
  background: "#fff",
  borderRadius: 16,
  border: "1px solid #eef0f3",
  padding: 24,
  display: "flex",
  flexDirection: "column",
  gap: 16,
};

function saveButtonStyle(loading: boolean): React.CSSProperties {
  return {
    display: "inline-flex",
    alignItems: "center",
    justifyContent: "center",
    gap: 8,
    height: 44,
    padding: "0 20px",
    background: loading ? "#5A6A7A" : "#0B1E3D",
    color: "#ffffff",
    fontWeight: 700,
    fontSize: 14,
    border: "none",
    borderRadius: 10,
    cursor: loading ? "not-allowed" : "pointer",
    fontFamily: "inherit",
    alignSelf: "flex-start",
  };
}

export default function DriverProfileClient({
  userNumber,
  initialName,
  email,
  initialPhone,
  initialPhoneVerified,
  initialHasSecurityQuestion,
  gender: initialGender,
  documents,
  verificationStatus,
  initialSavedAddresses,
}: Props) {
  const { dir, t } = useClientLocale();
  const selectStyle = getSelectStyle(dir);
  // Personal info
  const [name, setName] = useState(initialName);
  const [phone, setPhone] = useState(initialPhone);
  const [gender, setGender] = useState(initialGender);
  const [savingPersonal, setSavingPersonal] = useState(false);
  const [personalMsg, setPersonalMsg] = useState<{
    ok: boolean;
    text: string;
  } | null>(null);

  async function savePersonal(e: React.FormEvent) {
    e.preventDefault();
    if (!name.trim()) {
      setPersonalMsg({ ok: false, text: t("error.name_required") });
      return;
    }
    setSavingPersonal(true);
    setPersonalMsg(null);
    try {
      const res = await fetch("/api/auth/me", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: name.trim(),
          phone: phone.trim(),
          gender,
        }),
      });
      const data = await res.json();
      if (!res.ok) {
        setPersonalMsg({ ok: false, text: data.error ?? t("error.save_failed") });
        return;
      }
      setPersonalMsg({ ok: true, text: t("action.saved") });
    } catch {
      setPersonalMsg({ ok: false, text: t("error.network") });
    } finally {
      setSavingPersonal(false);
    }
  }

  const statusConfig: Record<
    typeof verificationStatus,
    { label: string; bg: string; color: string }
  > = {
    incomplete: { label: t("profile.status.incomplete"), bg: "#FFF3E0", color: "#E65100" },
    pending: { label: t("profile.status.pending"), bg: "#FFF8E1", color: "#F57F17" },
    verified: { label: t("profile.status.verified"), bg: "#E8F5E9", color: "#27AE60" },
  };
  const statusCfg = statusConfig[verificationStatus];

  const verificationCta =
    verificationStatus === "verified"
      ? t("verification.cta_view")
      : verificationStatus === "pending"
        ? t("verification.cta_view_submission")
        : t("verification.cta_complete");

  return (
    <div style={{ minHeight: "100dvh", background: "#f8f9fa" }}>
      <AppHeader
        authed
        email={email}
        role="driver"
        variant="app"
        backHref="/my-trips"
      />

      <style>{`
        .profile-shell { max-width: 560px; margin: 0 auto; padding: 32px 20px 48px; }
        .profile-columns { display: grid; grid-template-columns: 1fr; gap: 20px; align-items: start; }
        /* Grid items default to min-width:auto, which lets form controls' UA min-content size
           force the track (and page) wider than the viewport. Force them shrinkable. */
        .profile-columns > * { min-width: 0; }
        @media (min-width: 900px) {
          .profile-shell { max-width: 960px; padding: 44px 32px 72px; }
          .profile-columns { grid-template-columns: minmax(0, 1fr) 360px; gap: 32px; }
        }
      `}</style>

      <main dir={dir} className="profile-shell">
        {/* Avatar + name */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 16,
            marginBottom: 28,
          }}
        >
          <div
            style={{
              width: 104,
              height: 104,
              borderRadius: "50%",
              background: "#00C2A8",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              flexShrink: 0,
              overflow: "hidden",
              border: "3px solid #ffffff",
              boxShadow: "0 0 0 1px #e8edf0, 0 8px 20px rgba(11,30,61,0.1)",
            }}
          >
            {documents.profilePic ? (
              <img
                src={documents.profilePic}
                alt="Profile"
                style={{
                  width: "100%",
                  height: "100%",
                  objectFit: "cover",
                }}
              />
            ) : (
              <User size={48} color="#fff" aria-hidden="true" />
            )}
          </div>
          <div style={{ minWidth: 0 }}>
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 8,
                marginBottom: 2,
                flexWrap: "wrap",
              }}
            >
              <p
                style={{
                  margin: 0,
                  fontSize: 20,
                  fontWeight: 800,
                  color: "#0B1E3D",
                  letterSpacing: "-0.02em",
                }}
              >
                {initialName}
              </p>
              <span
                style={{
                  display: "inline-flex",
                  alignItems: "center",
                  padding: "3px 10px",
                  borderRadius: 20,
                  fontSize: 12,
                  fontWeight: 600,
                  background: statusCfg.bg,
                  color: statusCfg.color,
                  whiteSpace: "nowrap",
                }}
              >
                {statusCfg.label}
              </span>
            </div>
            <p style={{ margin: 0, fontSize: 13, color: "#5A6A7A", overflowWrap: "anywhere" }}>
              #{userNumber}
              {email ? ` · ${email}` : ""}
            </p>
          </div>
        </div>

        <div className="profile-columns">
          <div>

        {/* Personal information */}
        <Section title={t("profile.personal_info")}>
          <form onSubmit={savePersonal} noValidate style={cardStyle}>
            <div>
              <label htmlFor="p-name" style={labelStyle}>
                {t("profile.name")}{" "}
                <span aria-hidden="true" style={{ color: "#e74c3c" }}>
                  *
                </span>
              </label>
              <input
                id="p-name"
                type="text"
                required
                value={name}
                onChange={(e) => setName(e.target.value)}
                style={inputStyle}
              />
            </div>
            <div>
              <label htmlFor="p-phone" style={labelStyle}>
                {t("profile.phone")}
              </label>
              <div
                dir="ltr"
                style={{
                  ...inputStyle,
                  padding: 0,
                  display: "flex",
                  alignItems: "stretch",
                  overflow: "hidden",
                  direction: "ltr",
                }}
              >
                <span
                  dir="ltr"
                  style={{
                    display: "flex",
                    alignItems: "center",
                    padding: "0 12px",
                    fontWeight: 600,
                    color: "#0B1E3D",
                    background: "#eef1f3",
                    borderRight: dir === "ltr" ? "1.5px solid #e8edf0" : undefined,
                    borderLeft: dir === "rtl" ? "1.5px solid #e8edf0" : undefined,
                    direction: "ltr",
                  }}
                >
                  +20
                </span>
                <input
                  id="p-phone"
                  type="tel"
                  inputMode="numeric"
                  maxLength={10}
                  placeholder="1XXXXXXXXX"
                  value={phone.replace(/^\+?20/, "")}
                  onChange={(e) => {
                    const digits = e.target.value
                      .replace(/\D/g, "")
                      .slice(0, 10);
                    setPhone(digits ? `+20${digits}` : "");
                  }}
                  style={{
                    flex: 1,
                    minWidth: 0,
                    height: "100%",
                    padding: "0 14px",
                    border: "none",
                    outline: "none",
                    background: "transparent",
                    fontSize: 14,
                    fontFamily: "inherit",
                    color: "#0B1E3D",
                    boxSizing: "border-box",
                    textAlign: "left",
                    direction: "ltr",
                  }}
                />
              </div>
            </div>
            <div>
              <label htmlFor="p-gender" style={labelStyle}>
                {t("profile.gender")}
              </label>
              <select
                id="p-gender"
                value={gender}
                onChange={(e) => setGender(e.target.value as "male" | "female")}
                style={selectStyle}
              >
                <option value="male">{t("gender.male")}</option>
                <option value="female">{t("gender.female")}</option>
              </select>
            </div>
            {personalMsg && (
              <p
                role="status"
                aria-live="polite"
                style={{
                  fontSize: 13,
                  margin: 0,
                  color: personalMsg.ok ? "#27AE60" : "#e74c3c",
                }}
              >
                {personalMsg.text}
              </p>
            )}
            <button
              type="submit"
              disabled={savingPersonal}
              style={saveButtonStyle(savingPersonal)}
            >
              {savingPersonal ? (
                <Loader2 size={16} className="spin" aria-hidden="true" />
              ) : (
                <Check size={16} aria-hidden="true" />
              )}
              {savingPersonal ? t("action.saving") : t("profile.save")}
            </button>
          </form>
        </Section>

        {/* Vehicle & documents verification */}
        <Section title={t("verification.section_title")}>
          <div style={{ ...cardStyle, gap: 18 }}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <span
                  style={{
                    width: 38,
                    height: 38,
                    borderRadius: 10,
                    flexShrink: 0,
                    display: "inline-flex",
                    alignItems: "center",
                    justifyContent: "center",
                    background: "rgba(0,194,168,0.12)",
                    color: "#00877A",
                  }}
                >
                  <ShieldCheck size={19} aria-hidden="true" />
                </span>
                <div>
                  <p style={{ margin: 0, fontSize: 14, fontWeight: 700, color: "#0B1E3D" }}>
                    {t("profile.driver_details")} &amp; {t("profile.documents").toLowerCase()}
                  </p>
                  <p style={{ margin: "2px 0 0", fontSize: 12.5, color: "#5A6A7A" }}>
                    {t("verification.section_hint")}
                  </p>
                </div>
              </div>
              <span
                style={{
                  display: "inline-flex",
                  alignItems: "center",
                  padding: "3px 10px",
                  borderRadius: 20,
                  fontSize: 12,
                  fontWeight: 600,
                  background: statusCfg.bg,
                  color: statusCfg.color,
                  whiteSpace: "nowrap",
                  flexShrink: 0,
                }}
              >
                {statusCfg.label}
              </span>
            </div>

            <Link
              href="/profile/verification"
              style={{
                ...saveButtonStyle(false),
                textDecoration: "none",
                alignSelf: "stretch",
                justifyContent: "center",
              }}
            >
              {verificationCta}
              {dir === "rtl" ? <ArrowLeft size={16} aria-hidden="true" /> : <ArrowRight size={16} aria-hidden="true" />}
            </Link>
          </div>
        </Section>
          </div>

          <div>
            <p
              style={{
                margin: "0 0 12px",
                fontSize: 12,
                fontWeight: 800,
                letterSpacing: "0.04em",
                textTransform: "uppercase",
                color: "#00877A",
              }}
            >
              {t("profile.account_section")}
            </p>
            <ChangePasswordSection />
            <div style={{ marginTop: 20 }}>
              <PhoneVerificationCard initialVerified={initialPhoneVerified} />
            </div>
            <div style={{ marginTop: 20 }}>
              <SecurityQuestionSetupCard initialHasSecurityQuestion={initialHasSecurityQuestion} />
            </div>
            <div style={{ marginTop: 20 }}>
              <ReferralCard />
            </div>
            <div style={{ marginTop: 20 }}>
              <SavedAddressesSection initialAddresses={initialSavedAddresses} />
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

﻿"use client";
import { useEffect, useRef, useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { User, Phone, Mail, Check, Loader2, Camera, Globe } from "lucide-react";
import AppHeader from "@/components/layout/AppHeader";
import ChangePasswordSection from "@/components/shared/ChangePasswordSection";
import SavedAddressesSection from "@/components/shared/SavedAddressesSection";
import ReferralCard from "@/components/shared/ReferralCard";
import PhoneVerificationCard from "@/components/shared/PhoneVerificationCard";
import SecurityQuestionSetupCard from "@/components/shared/SecurityQuestionSetupCard";
import type { SavedAddress } from "@/types/shared";
import { useClientLocale } from "@/lib/i18n/client";
import {
  DEFAULT_REGION,
  REGION_LIST,
  regionFromCoordinates,
  type RegionCode,
} from "@/lib/config/regions";

interface Props {
  userNumber: number;
  initialName: string;
  email: string;
  initialPhone: string;
  initialPhoneVerified: boolean;
  initialHasSecurityQuestion: boolean;
  initialRegion: RegionCode | null;
  initialGender: "male" | "female" | null;
  initialProfilePic?: string | null;
  initialSavedAddresses: SavedAddress[];
}

export default function ProfileClient({
  userNumber,
  initialName,
  email,
  initialPhone,
  initialPhoneVerified,
  initialHasSecurityQuestion,
  initialRegion,
  initialGender,
  initialProfilePic,
  initialSavedAddresses,
}: Props) {
  const router = useRouter();
  const { t, dir, locale } = useClientLocale();
  const [name, setName] = useState(initialName);
  const [phone, setPhone] = useState(initialPhone);
  const [region, setRegion] = useState<RegionCode>(
    initialRegion ?? DEFAULT_REGION,
  );
  const [gender, setGender] = useState<"male" | "female" | "">(
    initialGender ?? "",
  );
  const [detectingRegion, setDetectingRegion] = useState(false);
  const [profilePic, setProfilePic] = useState(initialProfilePic ?? null);
  const [uploading, setUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement | null>(null);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState(false);

  // No region stored yet → derive it once from the browser's location fix.
  useEffect(() => {
    if (initialRegion || !navigator.geolocation) return;
    // eslint-disable-next-line react-hooks/set-state-in-effect -- shows a loading flag while the async geolocation fix resolves
    setDetectingRegion(true);
    navigator.geolocation.getCurrentPosition(
      async ({ coords }) => {
        const detected = regionFromCoordinates(
          coords.latitude,
          coords.longitude,
        );
        if (detected) {
          setRegion(detected);
          try {
            await fetch("/api/auth/me", {
              method: "PATCH",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({
                name: initialName,
                region: detected,
              }),
            });
            router.refresh();
          } catch {
            /* non-fatal */
          }
        }
        setDetectingRegion(false);
      },
      () => setDetectingRegion(false),
      { timeout: 8000 },
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  async function handlePicChange(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    setError("");
    try {
      const formData = new FormData();
      formData.append("file", file);
      const uploadRes = await fetch("/api/upload", {
        method: "POST",
        body: formData,
      });
      const uploadData = await uploadRes.json();
      if (!uploadRes.ok) {
        setError(uploadData.error ?? t("profile.upload_failed"));
        return;
      }
      const saveRes = await fetch("/api/auth/me", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: name.trim(),
          profilePic: uploadData.path,
        }),
      });
      const saveData = await saveRes.json();
      if (!saveRes.ok) {
        setError(saveData.error ?? t("profile.save_failed"));
        return;
      }
      setProfilePic(uploadData.path);
      router.refresh();
    } catch {
      setError(t("profile.network_error"));
    } finally {
      setUploading(false);
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  }

  async function handleSave(e: React.FormEvent) {
    e.preventDefault();
    if (!name.trim()) {
      setError(t("profile.name_required"));
      return;
    }
    setSaving(true);
    setError("");
    setSuccess(false);
    try {
      const res = await fetch("/api/auth/me", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: name.trim(),
          phone: phone.trim(),
          region,
          gender: gender || undefined,
        }),
      });
      const data = await res.json();
      if (!res.ok) {
        setError(data.error ?? t("profile.save_failed"));
        return;
      }
      setSuccess(true);
      setTimeout(() => setSuccess(false), 3000);
      router.refresh();
    } catch {
      setError(t("profile.network_error"));
    } finally {
      setSaving(false);
    }
  }

  return (
    <div style={{ minHeight: "100dvh", background: "#f8f9fa" }}>
      <AppHeader authed email={email} variant="app" backHref="/" />

      <style>{`
        .profile-shell { max-width: 520px; margin: 0 auto; padding: 32px 20px 48px; }
        .profile-columns { display: grid; grid-template-columns: 1fr; gap: 20px; align-items: start; }
        /* Grid items default to min-width:auto, which lets form controls' UA min-content size
           force the track (and page) wider than the viewport. Force them shrinkable. */
        .profile-columns > * { min-width: 0; }
        @media (min-width: 900px) {
          .profile-shell { max-width: 960px; padding: 44px 32px 72px; }
          .profile-columns { grid-template-columns: minmax(0, 1fr) 360px; gap: 32px; }
        }
      `}</style>

      <main dir={dir} className="profile-shell">
        {/* Avatar + name */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 16,
            marginBottom: 28,
          }}
        >
          <input
            ref={fileInputRef}
            type="file"
            accept="image/jpeg,image/png,image/webp"
            style={{ display: "none" }}
            onChange={handlePicChange}
          />
          <div style={{ position: "relative", flexShrink: 0 }}>
            <button
              type="button"
              onClick={() => fileInputRef.current?.click()}
              disabled={uploading}
              aria-label={t("profile.change_picture")}
              className="group"
              style={{
                position: "relative",
                width: 104,
                height: 104,
                borderRadius: "50%",
                background: "#00C2A8",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                flexShrink: 0,
                overflow: "hidden",
                border: "3px solid #ffffff",
                boxShadow: "0 0 0 1px #e8edf0, 0 8px 20px rgba(11,30,61,0.1)",
                padding: 0,
                cursor: uploading ? "default" : "pointer",
              }}
            >
              {profilePic ? (
                <img
                  src={profilePic}
                  alt={t("profile.profile_alt")}
                  style={{
                    width: "100%",
                    height: "100%",
                    objectFit: "cover",
                  }}
                />
              ) : (
                <User size={48} color="#fff" aria-hidden="true" />
              )}
              <div
                className="group-hover:opacity-100"
                style={{
                  position: "absolute",
                  inset: 0,
                  background: "rgba(11,30,61,0.5)",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  opacity: uploading ? 1 : 0,
                  transition: "opacity 0.15s",
                }}
              >
                {uploading ? (
                  <Loader2
                    size={22}
                    color="#fff"
                    className="animate-spin"
                    aria-hidden="true"
                  />
                ) : (
                  <Camera size={22} color="#fff" aria-hidden="true" />
                )}
              </div>
            </button>
            <span
              aria-hidden="true"
              style={{
                position: "absolute",
                bottom: 0,
                right: 0,
                width: 26,
                height: 26,
                borderRadius: "50%",
                background: "#0B1E3D",
                border: "2px solid #ffffff",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                pointerEvents: "none",
              }}
            >
              <Camera size={12} color="#fff" />
            </span>
          </div>
          <div style={{ minWidth: 0 }}>
            <p
              style={{
                margin: "0 0 2px",
                fontSize: 20,
                fontWeight: 800,
                color: "#0B1E3D",
                letterSpacing: "-0.02em",
              }}
            >
              {initialName}
            </p>
            <p
              style={{
                margin: 0,
                fontSize: 13,
                color: "#5A6A7A",
                overflowWrap: "anywhere",
              }}
            >
              #{userNumber}
              {email ? ` · ${email}` : ""}
            </p>
          </div>
        </div>

        <div className="profile-columns">
          <div>
            {/* Form card */}
            <form
              onSubmit={handleSave}
              noValidate
              style={{
                background: "#fff",
                borderRadius: 16,
                border: "1px solid #eef0f3",
                padding: "24px",
                display: "flex",
                flexDirection: "column",
                gap: 20,
              }}
            >
              <h1
                style={{
                  fontSize: 15,
                  fontWeight: 700,
                  color: "#0B1E3D",
                  margin: 0,
                }}
              >
                {t("profile.edit_profile")}
              </h1>

              {/* Name */}
              <div>
                <label
                  htmlFor="p-name"
                  style={{
                    fontSize: 13,
                    fontWeight: 600,
                    color: "#0B1E3D",
                    display: "block",
                    marginBottom: 6,
                  }}
                >
                  {t("profile.full_name")}{" "}
                  <span aria-hidden="true" style={{ color: "#e74c3c" }}>
                    *
                  </span>
                </label>
                <div style={{ position: "relative" }}>
                  <User
                    size={15}
                    aria-hidden="true"
                    style={{
                      position: "absolute",
                      left: dir === "rtl" ? undefined : 14,
                      right: dir === "rtl" ? 14 : undefined,
                      top: "50%",
                      transform: "translateY(-50%)",
                      color: "#9aa8b5",
                      pointerEvents: "none",
                    }}
                  />
                  <input
                    id="p-name"
                    type="text"
                    value={name}
                    required
                    autoComplete="name"
                    onChange={(e) => setName(e.target.value)}
                    style={{
                      width: "100%",
                      minWidth: 0,
                      height: 48,
                      paddingLeft: dir === "rtl" ? 14 : 38,
                      paddingRight: dir === "rtl" ? 38 : 14,
                      border: "1.5px solid #d0d8e0",
                      borderRadius: 10,
                      fontSize: 15,
                      color: "#0B1E3D",
                      fontFamily: "inherit",
                      background: "#fff",
                      outline: "none",
                      boxSizing: "border-box",
                      transition: "border-color 0.15s",
                    }}
                    onFocus={(e) =>
                      (e.currentTarget.style.borderColor = "#00C2A8")
                    }
                    onBlur={(e) =>
                      (e.currentTarget.style.borderColor = "#d0d8e0")
                    }
                  />
                </div>
              </div>

              {/* Email — read only */}
              <div>
                <label
                  htmlFor="p-email"
                  style={{
                    fontSize: 13,
                    fontWeight: 600,
                    color: "#0B1E3D",
                    display: "block",
                    marginBottom: 6,
                  }}
                >
                  {t("profile.email")}
                </label>
                <div style={{ position: "relative" }}>
                  <Mail
                    size={15}
                    aria-hidden="true"
                    style={{
                      position: "absolute",
                      left: dir === "rtl" ? undefined : 14,
                      right: dir === "rtl" ? 14 : undefined,
                      top: "50%",
                      transform: "translateY(-50%)",
                      color: "#9aa8b5",
                      pointerEvents: "none",
                    }}
                  />
                  <input
                    id="p-email"
                    type="email"
                    value={email}
                    readOnly
                    aria-readonly="true"
                    style={{
                      width: "100%",
                      minWidth: 0,
                      height: 48,
                      paddingLeft: dir === "rtl" ? 14 : 38,
                      paddingRight: dir === "rtl" ? 38 : 14,
                      border: "1.5px solid #eef0f3",
                      borderRadius: 10,
                      fontSize: 15,
                      color: "#9aa8b5",
                      fontFamily: "inherit",
                      background: "#f8f9fa",
                      outline: "none",
                      boxSizing: "border-box",
                      cursor: "not-allowed",
                    }}
                  />
                </div>
                <p
                  style={{
                    fontSize: 12,
                    color: "#9aa8b5",
                    margin: "5px 0 0 2px",
                  }}
                >
                  {t("profile.email_readonly_note")}
                </p>
              </div>

              {/* Phone */}
              <div>
                <label
                  htmlFor="p-phone"
                  style={{
                    fontSize: 13,
                    fontWeight: 600,
                    color: "#0B1E3D",
                    display: "block",
                    marginBottom: 6,
                  }}
                >
                  {t("profile.phone_number")}
                </label>
                <div
                  dir="ltr"
                  style={{
                    width: "100%",
                    height: 48,
                    padding: 0,
                    display: "flex",
                    alignItems: "stretch",
                    overflow: "hidden",
                    border: "1.5px solid #d0d8e0",
                    borderRadius: 10,
                    background: "#fff",
                    boxSizing: "border-box",
                    transition: "border-color 0.15s",
                    direction: "ltr",
                  }}
                  className="phone-field"
                  onFocusCapture={(e) =>
                    (e.currentTarget.style.borderColor = "#00C2A8")
                  }
                  onBlurCapture={(e) =>
                    (e.currentTarget.style.borderColor = "#d0d8e0")
                  }
                >
                  <span
                    dir="ltr"
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: 6,
                      padding: "0 12px",
                      fontWeight: 600,
                      color: "#0B1E3D",
                      background: "#eef1f3",
                      borderRight: "1.5px solid #d0d8e0",
                      flexShrink: 0,
                      direction: "ltr",
                    }}
                  >
                    <Phone size={15} color="#9aa8b5" aria-hidden="true" />
                    +20
                  </span>
                  <input
                    id="p-phone"
                    type="tel"
                    inputMode="numeric"
                    maxLength={10}
                    autoComplete="tel"
                    placeholder={t("profile.phone_placeholder")}
                    value={phone.replace(/^\+?20/, "")}
                    onChange={(e) => {
                      const digits = e.target.value
                        .replace(/\D/g, "")
                        .slice(0, 10);
                      setPhone(digits ? `+20${digits}` : "");
                    }}
                    style={{
                      flex: 1,
                      minWidth: 0,
                      height: "100%",
                      padding: "0 14px",
                      border: "none",
                      outline: "none",
                      background: "transparent",
                      fontSize: 15,
                      fontFamily: "inherit",
                      color: "#0B1E3D",
                      boxSizing: "border-box",
                      direction: "ltr",
                      textAlign: "left",
                    }}
                  />
                </div>
              </div>

              {/* Gender */}
              <div>
                <label
                  htmlFor="p-gender"
                  style={{
                    fontSize: 13,
                    fontWeight: 600,
                    color: "#0B1E3D",
                    display: "block",
                    marginBottom: 6,
                  }}
                >
                  {t("profile.gender")}
                </label>
                <select
                  id="p-gender"
                  value={gender}
                  onChange={(event) =>
                    setGender(event.target.value as "male" | "female" | "")
                  }
                  style={{
                    width: "100%",
                    height: 48,
                    padding: "0 14px",
                    border: "1.5px solid #d0d8e0",
                    borderRadius: 10,
                    fontSize: 15,
                    color: "#0B1E3D",
                    fontFamily: "inherit",
                    background: "#fff",
                  }}
                >
                  <option value="">{t("profile.gender")}</option>
                  <option value="male">{t("gender.male")}</option>
                  <option value="female">{t("gender.female")}</option>
                </select>
              </div>

              {/* Region */}
              <div>
                <label
                  htmlFor="p-region"
                  style={{
                    fontSize: 13,
                    fontWeight: 600,
                    color: "#0B1E3D",
                    display: "block",
                    marginBottom: 6,
                  }}
                >
                  {t("profile.region")}
                </label>
                <div style={{ position: "relative" }}>
                  <Globe
                    size={15}
                    aria-hidden="true"
                    style={{
                      position: "absolute",
                      left: dir === "rtl" ? undefined : 14,
                      right: dir === "rtl" ? 14 : undefined,
                      top: "50%",
                      transform: "translateY(-50%)",
                      color: "#9aa8b5",
                      pointerEvents: "none",
                    }}
                  />
                  <select
                    id="p-region"
                    value={region}
                    onChange={(e) => setRegion(e.target.value as RegionCode)}
                    style={{
                      width: "100%",
                      minWidth: 0,
                      height: 48,
                      paddingLeft: dir === "rtl" ? 14 : 38,
                      paddingRight: dir === "rtl" ? 38 : 14,
                      border: "1.5px solid #d0d8e0",
                      borderRadius: 10,
                      fontSize: 15,
                      color: "#0B1E3D",
                      fontFamily: "inherit",
                      background: "#fff",
                      outline: "none",
                      boxSizing: "border-box",
                      cursor: "pointer",
                    }}
                  >
                    {REGION_LIST.map((r) => (
                      <option key={r.code} value={r.code}>
                        {locale === "ar" ? r.labelAr : r.label}
                      </option>
                    ))}
                  </select>
                </div>
                <p
                  style={{
                    fontSize: 12,
                    color: "#9aa8b5",
                    margin: "5px 0 0 2px",
                  }}
                >
                  {detectingRegion
                    ? t("profile.region_detecting")
                    : t("profile.region_note")}
                </p>
              </div>

              {error && (
                <p
                  role="alert"
                  aria-live="assertive"
                  style={{
                    fontSize: 13,
                    color: "#e74c3c",
                    background: "rgba(231,76,60,0.07)",
                    border: "1px solid rgba(231,76,60,0.2)",
                    borderRadius: 8,
                    padding: "10px 14px",
                    margin: 0,
                  }}
                >
                  {error}
                </p>
              )}

              {success && (
                <p
                  role="status"
                  aria-live="polite"
                  style={{
                    fontSize: 13,
                    color: "#27AE60",
                    background: "rgba(39,174,96,0.07)",
                    border: "1px solid rgba(39,174,96,0.25)",
                    borderRadius: 8,
                    padding: "10px 14px",
                    margin: 0,
                    display: "flex",
                    alignItems: "center",
                    gap: 8,
                  }}
                >
                  <Check size={14} aria-hidden="true" />
                  {t("profile.updated_success")}
                </p>
              )}

              <button
                type="submit"
                disabled={saving}
                style={{
                  height: 52,
                  background: saving ? "#9aa8b5" : "#0B1E3D",
                  color: "#fff",
                  fontWeight: 700,
                  fontSize: 15,
                  border: "none",
                  borderRadius: 12,
                  cursor: saving ? "not-allowed" : "pointer",
                  fontFamily: "inherit",
                  transition: "background 0.2s",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  gap: 8,
                }}
                onMouseEnter={(e) => {
                  if (!saving) e.currentTarget.style.background = "#00C2A8";
                }}
                onMouseLeave={(e) => {
                  if (!saving) e.currentTarget.style.background = "#0B1E3D";
                }}
              >
                {saving ? (
                  <>
                    <Loader2
                      size={16}
                      aria-hidden="true"
                      style={{ animation: "spin 0.7s linear infinite" }}
                    />
                    {t("profile.saving")}
                  </>
                ) : (
                  t("profile.save_changes")
                )}
              </button>
            </form>

            <div style={{ marginTop: 20 }}>
              <ChangePasswordSection />
            </div>

            <div style={{ marginTop: 20 }}>
              <PhoneVerificationCard initialVerified={initialPhoneVerified} />
            </div>

            <div style={{ marginTop: 20 }}>
              <SecurityQuestionSetupCard
                initialHasSecurityQuestion={initialHasSecurityQuestion}
              />
            </div>

            <div
              style={{
                display: "flex",
                gap: 12,
                marginTop: 20,
                flexWrap: "wrap",
              }}
            >
              <Link
                href="/create"
                style={{
                  fontSize: 14,
                  fontWeight: 600,
                  color: "#00C2A8",
                  textDecoration: "none",
                  padding: "10px 18px",
                  background: "#eff7f6",
                  border: "1.5px solid #c8e8e4",
                  borderRadius: 10,
                }}
              >
                {t("profile.book_a_ride")}
              </Link>
            </div>
          </div>

          <div>
            <p
              style={{
                margin: "0 0 12px",
                fontSize: 12,
                fontWeight: 800,
                letterSpacing: "0.04em",
                textTransform: "uppercase",
                color: "#00877A",
              }}
            >
              {t("profile.account_section")}
            </p>
            <ReferralCard />
            <div style={{ marginTop: 20 }}>
              <SavedAddressesSection initialAddresses={initialSavedAddresses} />
            </div>
          </div>
        </div>
      </main>
      <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
    </div>
  );
}

