"use client";

import { useEffect, useMemo, useState, type FormEvent } from "react";

type PointLike = {
  address?: string;
  lat?: number;
  lng?: number;
};

type StationLike = {
  id?: number;
  name?: string;
  lat: number;
  lng: number;
};

type TripOption = {
  _id: string;
  tripNumber?: number;
  date: string;
  pickupTime: string;
  arrivalTime: string;
  pickup: PointLike;
  dropoff: PointLike;
  pickupStation?: StationLike;
  dropoffStation?: StationLike;
  vehicleType: string;
  rideType: string;
  priceEgp: number;
  numberOfPassengers?: number;
  userId: string;
};

type DriverOption = {
  _id: string;
  name: string;
  phone?: string;
  email?: string;
};

type MatchRideFormProps = {
  initialDate: string;
  drivers: DriverOption[];
  trips: TripOption[];
};

type PassengerInput = {
  pickupOrder: number;
  dropoffOrder: number;
  numberOfPassengers: number;
  priceEgp: number;
  seatNumbers?: number[];
};

const VEHICLE_OPTIONS = [
  { value: "private_car", label: "Private Car" },
  { value: "shared_car", label: "Shared Car" },
  { value: "taxi_private", label: "Private Taxi" },
  { value: "taxi_shared", label: "Shared Taxi" },
  { value: "van_shared", label: "Shared Van" },
  { value: "microbus_shared", label: "Shared Microbus" },
];

export default function MatchRideForm({
  initialDate,
  drivers,
  trips,
}: MatchRideFormProps) {
  const [tripDateFilter, setTripDateFilter] = useState(initialDate);
  const [driverId, setDriverId] = useState("");
  const [date, setDate] = useState(initialDate);
  const [rideType, setRideType] = useState("shared");
  const [vehicleType, setVehicleType] = useState("taxi_shared");
  const [startTime, setStartTime] = useState("07:00");
  const [endTime, setEndTime] = useState("18:30");
  // Once the admin edits the time window by hand, stop overwriting it —
  // otherwise every driver shift (capped at 8h) would never contain it.
  const [timeTouched, setTimeTouched] = useState(false);
  const [selectedTripIds, setSelectedTripIds] = useState<string[]>([]);
  const [passengerInputs, setPassengerInputs] = useState<
    Record<string, PassengerInput>
  >({});
  const [submitting, setSubmitting] = useState(false);
  const [feedback, setFeedback] = useState<{
    type: "success" | "error";
    message: string;
  } | null>(null);

  const [orderedPoints, setOrderedPoints] = useState<
    Array<{
      id: string;
      type: "pickup" | "dropoff";
      tripId: string;
      tripNumber?: number;
      address: string;
      point: PointLike;
    }>
  >([]);

  // No auto-selected driver: leaving it blank is the intended default
  // (broadcast the ride to every eligible driver instead of force-assigning).

  const filteredTrips = useMemo(() => {
    return trips.filter((trip) => trip.date === tripDateFilter);
  }, [trips, tripDateFilter]);

  // Narrow the ride window to the selected trips' own times so it can
  // actually fit inside a driver's (max 8h) recurring availability shift.
  useEffect(() => {
    if (timeTouched || selectedTripIds.length === 0) return;
    const selected = trips.filter((trip) => selectedTripIds.includes(String(trip._id)));
    const pickupTimes = selected.map((trip) => trip.pickupTime).filter(Boolean);
    const arrivalTimes = selected.map((trip) => trip.arrivalTime).filter(Boolean);
    if (pickupTimes.length === 0 || arrivalTimes.length === 0) return;
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setStartTime(pickupTimes.sort()[0]);
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setEndTime(arrivalTimes.sort().at(-1)!);
  }, [selectedTripIds, trips, timeTouched]);

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setPassengerInputs((current) => {
      const next: Record<string, PassengerInput> = { ...current };
      selectedTripIds.forEach((tripId, index) => {
        const existing = next[tripId] ?? {};
        const selectedTrip = trips.find((trip) => String(trip._id) === tripId);
        const pickupOrder = rideType === "shared" ? index + 1 : 1;
        const dropoffOrder =
          rideType === "shared" ? selectedTripIds.length - index : 1;
        next[tripId] = {
          pickupOrder: existing.pickupOrder ?? pickupOrder,
          dropoffOrder: existing.dropoffOrder ?? dropoffOrder,
          numberOfPassengers:
            existing.numberOfPassengers ??
            selectedTrip?.numberOfPassengers ??
            1,
          priceEgp: existing.priceEgp ?? selectedTrip?.priceEgp ?? 0,
        };
      });
      return next;
    });
  }, [rideType, selectedTripIds, trips]);

  useEffect(() => {
    const currentIds = new Set(orderedPoints.map((p) => p.id));
    const newPoints: Array<{
      id: string;
      type: "pickup" | "dropoff";
      tripId: string;
      tripNumber?: number;
      address: string;
      point: PointLike;
    }> = [];

    selectedTripIds.forEach((tripId) => {
      const trip = trips.find((t) => String(t._id) === tripId);
      if (!trip) return;

      const pickupId = `pickup-${tripId}`;
      const dropoffId = `dropoff-${tripId}`;

      // Shared rides route via stations, not raw origin/destination
      const pickupPoint = trip.pickupStation
        ? {
            lat: trip.pickupStation.lat,
            lng: trip.pickupStation.lng,
            address: trip.pickupStation.name ?? "Pickup station",
          }
        : trip.pickup;
      const dropoffPoint = trip.dropoffStation
        ? {
            lat: trip.dropoffStation.lat,
            lng: trip.dropoffStation.lng,
            address: trip.dropoffStation.name ?? "Dropoff station",
          }
        : trip.dropoff;

      if (!currentIds.has(pickupId)) {
        newPoints.push({
          id: pickupId,
          type: "pickup",
          tripId,
          tripNumber: trip.tripNumber,
          address:
            trip.pickupStation?.name ??
            trip.pickup?.address ??
            "Pickup location",
          point: pickupPoint,
        });
      }

      if (!currentIds.has(dropoffId)) {
        newPoints.push({
          id: dropoffId,
          type: "dropoff",
          tripId,
          tripNumber: trip.tripNumber,
          address:
            trip.dropoffStation?.name ??
            trip.dropoff?.address ??
            "Dropoff location",
          point: dropoffPoint,
        });
      }
    });

    const validTripIds = new Set(selectedTripIds);
    const updated = orderedPoints
      .filter((p) => validTripIds.has(p.tripId))
      .concat(newPoints);

    // Recompute ordered points from selection
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setOrderedPoints(updated);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedTripIds, trips]);

  function movePoint(index: number, direction: "up" | "down") {
    const targetIndex = direction === "up" ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= orderedPoints.length) return;
    const next = [...orderedPoints];
    const temp = next[index];
    next[index] = next[targetIndex];
    next[targetIndex] = temp;
    setOrderedPoints(next);
  }

  function toggleTrip(tripId: string) {
    setSelectedTripIds((current) => {
      if (current.includes(tripId)) {
        return current.filter((value) => value !== tripId);
      }
      return [...current, tripId];
    });
  }

  function updatePassengerInput(
    tripId: string,
    field: keyof PassengerInput,
    value: string | number | number[],
  ) {
    setPassengerInputs((current) => ({
      ...current,
      [tripId]: {
        ...current[tripId],
        [field]: Array.isArray(value)
          ? value
          : field === "numberOfPassengers" ||
              field === "priceEgp" ||
              field === "pickupOrder" ||
              field === "dropoffOrder"
            ? Number(value)
            : value,
      },
    }));
  }

  async function onSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setFeedback(null);

    if (selectedTripIds.length === 0) {
      setFeedback({
        type: "error",
        message: "Choose at least one trip to match into a ride.",
      });
      return;
    }

    const route = orderedPoints.map((pt) => {
      const input = passengerInputs[pt.tripId] ?? { numberOfPassengers: 1 };
      const paxCount = input.numberOfPassengers || 1;
      return {
        point: pt.point,
        boarding: pt.type === "pickup" ? paxCount : 0,
        alighting: pt.type === "dropoff" ? paxCount : 0,
        waitingMinutes: 0,
      };
    });

    const passengers = selectedTripIds.map((tripId) => {
      const trip = trips.find((item) => String(item._id) === tripId);
      const input = passengerInputs[tripId] ?? {
        pickupOrder: 1,
        dropoffOrder: 1,
        numberOfPassengers: 1,
        priceEgp: 0,
      };
      const pIdx = orderedPoints.findIndex((p) => p.id === `pickup-${tripId}`);
      const dIdx = orderedPoints.findIndex((p) => p.id === `dropoff-${tripId}`);
      return {
        tripId,
        userId: trip?.userId,
        pickup: trip?.pickup,
        dropoff: trip?.dropoff,
        pickupOrder: pIdx >= 0 ? pIdx + 1 : input.pickupOrder,
        dropoffOrder: dIdx >= 0 ? dIdx + 1 : input.dropoffOrder,
        numberOfPassengers: input.numberOfPassengers,
        priceEgp: input.priceEgp,
        seatNumbers: input.seatNumbers ?? [],
      };
    });

    setSubmitting(true);

    try {
      const response = await fetch("/api/ride", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          driverId: driverId || null,
          date,
          vehicleType,
          rideType,
          startTime,
          endTime,
          passengers,
          route,
        }),
      });

      const payload = await response.json();
      if (!response.ok || !payload?.data) {
        throw new Error(payload?.error || "The ride could not be created.");
      }

      const createdRide = payload.data as {
        driverId?: string | null;
        offeredToDriverIds?: unknown[];
        needsManualAssignment?: boolean;
      };
      const tripLabel = `${passengers.length} trip${passengers.length > 1 ? "s" : ""}`;
      const eligibleCount = createdRide.offeredToDriverIds?.length ?? 0;
      const broadcastNote = createdRide.driverId
        ? ""
        : createdRide.needsManualAssignment
          ? " No drivers matched this time/day/vehicle — it needs manual assignment."
          : ` Offered to ${eligibleCount} eligible driver${eligibleCount === 1 ? "" : "s"}.`;

      setFeedback({
        type: "success",
        message: `Ride created successfully with ${tripLabel}.${broadcastNote}`,
      });
      setSelectedTripIds([]);
      setPassengerInputs({});
      setOrderedPoints([]);
      setTimeTouched(false);
    } catch (error) {
      setFeedback({
        type: "error",
        message: error instanceof Error ? error.message : "Unexpected error",
      });
    } finally {
      setSubmitting(false);
    }
  }

  const totalSelectedPassengers = selectedTripIds.reduce((sum, tripId) => {
    return sum + (passengerInputs[tripId]?.numberOfPassengers ?? 0);
  }, 0);

  return (
    <section className="match-form">
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@600;700&family=Inter:wght@400;500;600&family=JetBrains+Mono:wght@500;600&display=swap');

        .match-form {
          --ink: var(--color-primary);
          --teal: var(--color-secondary);
          --teal-deep: var(--color-secondary-deep);
          --amber: var(--color-accent);
          --amber-deep: var(--color-accent-deep);
          --slate: var(--color-muted);
          --line: var(--color-border);
          --canvas: var(--color-surface);
          font-family: 'Inter', system-ui, sans-serif;
          background: var(--color-panel);
          border: 1px solid var(--line);
          border-radius: 18px;
          box-shadow: 0 10px 35px var(--color-shadow);
          padding: 24px;
          margin-top: 20px;
          border-top: 3px solid var(--teal);
        }
        .match-form * { box-sizing: border-box; }
        .match-form .display { font-family: 'Space Grotesk', system-ui, sans-serif; }
        .match-form .mono { font-family: 'JetBrains Mono', ui-monospace, monospace; }

        .match-form .field-label {
          font-size: 12px;
          font-weight: 700;
          color: var(--slate);
          text-transform: uppercase;
          letter-spacing: 0.06em;
        }

        .match-form .field {
          border: 1px solid var(--color-border);
          border-radius: 10px;
          padding: 10px 12px;
          font-size: 14px;
          color: var(--ink);
          background: var(--color-panel);
          width: 100%;
          font-family: 'Inter', system-ui, sans-serif;
          transition: border-color 0.12s ease, box-shadow 0.12s ease;
        }
        .match-form .field:hover { border-color: var(--color-muted); }
        .match-form .field:focus-visible {
          outline: none;
          border-color: var(--teal);
          box-shadow: 0 0 0 3px var(--color-secondary-tint);
        }

        .match-form .trip-card {
          border: 1px solid var(--line);
          border-radius: 12px;
          padding: 12px;
          background: var(--color-background);
          transition: border-color 0.12s ease, background 0.12s ease;
        }
        .match-form .trip-card.selected {
          border-color: var(--teal);
          background: var(--color-secondary-tint);
        }
        .match-form .trip-check {
          display: flex;
          align-items: center;
          gap: 10px;
          font-weight: 600;
          color: var(--ink);
          cursor: pointer;
        }
        .match-form .trip-check input[type="checkbox"] {
          width: 17px;
          height: 17px;
          accent-color: var(--teal-deep);
          cursor: pointer;
        }

        /* Route order strip: pickup -> dropoff is genuine sequence data for a
           shared ride, so a connected order badge pair earns its place here. */
        .order-strip {
          display: flex;
          align-items: center;
          gap: 8px;
          margin-top: 10px;
          padding-top: 10px;
          border-top: 1px dashed var(--line);
        }
        .order-badge {
          display: inline-flex;
          align-items: center;
          justify-content: center;
          min-width: 26px;
          height: 26px;
          padding: 0 6px;
          border-radius: 999px;
          font-family: 'JetBrains Mono', ui-monospace, monospace;
          font-size: 12px;
          font-weight: 600;
          background: var(--ink);
          color: var(--color-on-primary);
        }
        .order-track {
          flex: 1;
          height: 1px;
          background-image: repeating-linear-gradient(to right, var(--teal) 0 6px, var(--color-transparent) 6px 11px);
          opacity: 0.6;
        }
        .order-badge.drop { background: var(--amber-deep); }

        .match-form .submit-btn {
          border: 0;
          border-radius: 999px;
          padding: 12px 20px;
          background: var(--ink);
          color: var(--color-on-primary);
          font-weight: 700;
          font-size: 14px;
          width: fit-content;
          display: inline-flex;
          align-items: center;
          gap: 8px;
          cursor: pointer;
          transition: opacity 0.12s ease, transform 0.12s ease;
        }
        .match-form .submit-btn:hover:not(:disabled) { opacity: 0.88; }
        .match-form .submit-btn:active:not(:disabled) { transform: translateY(1px); }
        .match-form .submit-btn:disabled { cursor: wait; opacity: 0.7; }
        .match-form .submit-btn:focus-visible {
          outline: 2px solid var(--teal-deep);
          outline-offset: 2px;
        }

        .match-form select.field {
          appearance: none;
          background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='10' height='6'><path d='M0 0l5 6 5-6z' fill='%235A6A7A'/></svg>");
          background-repeat: no-repeat;
          background-position: right 12px center;
          padding-right: 30px;
        }

        @media (prefers-reduced-motion: reduce) {
          .match-form .field, .match-form .trip-card, .match-form .submit-btn { transition: none; }
        }
      `}</style>

      <div
        style={{
          display: "flex",
          alignItems: "flex-start",
          justifyContent: "space-between",
          gap: 12,
          flexWrap: "wrap",
          marginBottom: 18,
        }}
      >
        <div>
          <h2
            className="display"
            style={{
              margin: 0,
              fontSize: 20,
              fontWeight: 700,
              color: "var(--ink)",
            }}
          >
            Create ride from matched trips
          </h2>
          <p style={{ margin: "4px 0 0", color: "var(--slate)", fontSize: 14 }}>
            Pick one or more trips to turn into a shared or private ride.
            Optionally choose a driver to assign directly, or leave it blank
            to broadcast the ride to every eligible driver (matched by their
            recurring weekly availability) so the first to accept is
            assigned.
          </p>
        </div>
        {selectedTripIds.length > 0 && (
          <span
            className="mono"
            style={{
              fontSize: 12,
              fontWeight: 600,
              color: "var(--teal-deep)",
              background: "var(--color-secondary-tint)",
              border: "1px solid var(--color-secondary)",
              borderRadius: 999,
              padding: "6px 12px",
            }}
          >
            {selectedTripIds.length} trip{selectedTripIds.length > 1 ? "s" : ""}{" "}
            · {totalSelectedPassengers} passenger
            {totalSelectedPassengers !== 1 ? "s" : ""}
          </span>
        )}
      </div>

      <form onSubmit={onSubmit} style={{ display: "grid", gap: 16 }}>
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))",
            gap: 12,
          }}
        >
          <label style={{ display: "grid", gap: 6 }}>
            <span className="field-label">Driver (optional — blank broadcasts to eligible drivers)</span>
            <select
              value={driverId}
              onChange={(e) => setDriverId(e.target.value)}
              className="field"
            >
              <option value="">Broadcast to eligible drivers</option>
              {drivers.map((driver) => (
                <option key={String(driver._id)} value={String(driver._id)}>
                  {driver.name} {driver.phone ? `· ${driver.phone}` : ""}
                </option>
              ))}
            </select>
          </label>

          <label style={{ display: "grid", gap: 6 }}>
            <span className="field-label">Ride date</span>
            <input
              type="date"
              value={date}
              onChange={(e) => setDate(e.target.value)}
              className="field"
            />
          </label>

          <label style={{ display: "grid", gap: 6 }}>
            <span className="field-label">Start time</span>
            <input
              type="time"
              value={startTime}
              onChange={(e) => {
                setTimeTouched(true);
                setStartTime(e.target.value);
              }}
              className="field"
            />
          </label>

          <label style={{ display: "grid", gap: 6 }}>
            <span className="field-label">End time</span>
            <input
              type="time"
              value={endTime}
              onChange={(e) => {
                setTimeTouched(true);
                setEndTime(e.target.value);
              }}
              className="field"
            />
          </label>

          <label style={{ display: "grid", gap: 6 }}>
            <span className="field-label">Ride type</span>
            <select
              value={rideType}
              onChange={(e) => setRideType(e.target.value)}
              className="field"
            >
              <option value="shared">Shared</option>
              <option value="private">Private</option>
            </select>
          </label>

          <label style={{ display: "grid", gap: 6 }}>
            <span className="field-label">Vehicle type</span>
            <select
              value={vehicleType}
              onChange={(e) => setVehicleType(e.target.value)}
              className="field"
            >
              {VEHICLE_OPTIONS.map((option) => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </select>
          </label>
        </div>

        <div style={{ display: "grid", gap: 10 }}>
          <div
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              gap: 10,
              flexWrap: "wrap",
            }}
          >
            <label style={{ display: "grid", gap: 6, minWidth: 220 }}>
              <span className="field-label">Trip date filter</span>
              <input
                type="date"
                value={tripDateFilter}
                onChange={(e) => setTripDateFilter(e.target.value)}
                className="field"
              />
            </label>
            <span style={{ color: "var(--slate)", fontSize: 13 }}>
              {filteredTrips.length} trips available
            </span>
          </div>

          <div
            style={{
              display: "grid",
              gap: 10,
              maxHeight: 320,
              overflowY: "auto",
              paddingRight: 4,
            }}
          >
            {filteredTrips.length === 0 ? (
              <div
                style={{
                  border: "1px dashed var(--color-border)",
                  borderRadius: 12,
                  padding: 16,
                  color: "var(--slate)",
                }}
              >
                No trips are available for this date yet.
              </div>
            ) : (
              filteredTrips.map((trip) => {
                const tripId = String(trip._id);
                const isSelected = selectedTripIds.includes(tripId);
                const input = passengerInputs[tripId] ?? {
                  pickupOrder: 1,
                  dropoffOrder: 1,
                  numberOfPassengers: trip.numberOfPassengers ?? 1,
                  priceEgp: trip.priceEgp ?? 0,
                };
                return (
                  <div
                    key={tripId}
                    className={`trip-card${isSelected ? " selected" : ""}`}
                  >
                    <div
                      style={{
                        display: "flex",
                        justifyContent: "space-between",
                        alignItems: "flex-start",
                        gap: 10,
                      }}
                    >
                      <label className="trip-check">
                        <input
                          type="checkbox"
                          checked={isSelected}
                          onChange={() => toggleTrip(tripId)}
                        />
                        <span>
                          Trip #{trip.tripNumber ?? "—"} · {trip.pickupTime} →{" "}
                          {trip.arrivalTime}
                        </span>
                      </label>
                      <span
                        className="mono"
                        style={{
                          color: "var(--teal-deep)",
                          fontWeight: 700,
                          fontSize: 13,
                        }}
                      >
                        EGP {trip.priceEgp}
                      </span>
                    </div>

                    {isSelected && (
                      <>
                        <div className="order-strip">
                          <span className="order-badge" title="Pickup order">
                            {input.pickupOrder}
                          </span>
                          <span className="order-track" aria-hidden="true" />
                          <span
                            className="order-badge drop"
                            title="Dropoff order"
                          >
                            {input.dropoffOrder}
                          </span>
                        </div>
                        <div
                          style={{
                            display: "grid",
                            gridTemplateColumns:
                              "repeat(auto-fit, minmax(110px, 1fr))",
                            gap: 10,
                            marginTop: 10,
                          }}
                        >
                          <label style={{ display: "grid", gap: 5 }}>
                            <span
                              className="field-label"
                              style={{ fontSize: 11 }}
                            >
                              Assign Chair
                            </span>
                            <select
                              value={input.seatNumbers?.[0] ?? ""}
                              onChange={(e) => {
                                const startSeat = Number(e.target.value);
                                const count = input.numberOfPassengers || 1;
                                const seats = startSeat
                                  ? Array.from(
                                      { length: count },
                                      (_, i) => startSeat + i,
                                    )
                                  : [];
                                updatePassengerInput(
                                  tripId,
                                  "seatNumbers",
                                  seats,
                                );
                              }}
                              className="field"
                            >
                              <option value="">Auto Seat</option>
                              {Array.from(
                                {
                                  length: vehicleType.includes("microbus")
                                    ? 9
                                    : vehicleType.includes("van")
                                      ? 5
                                      : 3,
                                },
                                (_, i) => i + 1,
                              ).map((sNo) => (
                                <option key={sNo} value={sNo}>
                                  Chair #{sNo}
                                </option>
                              ))}
                            </select>
                          </label>
                          <label style={{ display: "grid", gap: 5 }}>
                            <span
                              className="field-label"
                              style={{ fontSize: 11 }}
                            >
                              Pickup order
                            </span>
                            <input
                              type="number"
                              min={1}
                              value={input.pickupOrder}
                              onChange={(e) =>
                                updatePassengerInput(
                                  tripId,
                                  "pickupOrder",
                                  e.target.value,
                                )
                              }
                              className="field"
                            />
                          </label>
                          <label style={{ display: "grid", gap: 5 }}>
                            <span
                              className="field-label"
                              style={{ fontSize: 11 }}
                            >
                              Dropoff order
                            </span>
                            <input
                              type="number"
                              min={1}
                              value={input.dropoffOrder}
                              onChange={(e) =>
                                updatePassengerInput(
                                  tripId,
                                  "dropoffOrder",
                                  e.target.value,
                                )
                              }
                              className="field"
                            />
                          </label>
                          <label style={{ display: "grid", gap: 5 }}>
                            <span
                              className="field-label"
                              style={{ fontSize: 11 }}
                            >
                              Passengers
                            </span>
                            <input
                              type="number"
                              min={1}
                              value={input.numberOfPassengers}
                              onChange={(e) =>
                                updatePassengerInput(
                                  tripId,
                                  "numberOfPassengers",
                                  e.target.value,
                                )
                              }
                              className="field"
                            />
                          </label>
                          <label style={{ display: "grid", gap: 5 }}>
                            <span
                              className="field-label"
                              style={{ fontSize: 11 }}
                            >
                              Price
                            </span>
                            <input
                              type="number"
                              min={0}
                              value={input.priceEgp}
                              onChange={(e) =>
                                updatePassengerInput(
                                  tripId,
                                  "priceEgp",
                                  e.target.value,
                                )
                              }
                              className="field"
                            />
                          </label>
                        </div>
                      </>
                    )}
                  </div>
                );
              })
            )}
          </div>
        </div>

        {orderedPoints.length > 0 && (
          <div
            style={{
              marginTop: 14,
              padding: 16,
              background: "var(--color-surface)",
              border: "1px solid var(--color-border)",
              borderRadius: 14,
            }}
          >
            <h3
              className="display"
              style={{
                margin: "0 0 4px",
                fontSize: 15,
                fontWeight: 700,
                color: "var(--color-primary)",
              }}
            >
              Route Points Sequence (First Station → Final Destination)
            </h3>
            <p
              style={{
                margin: "0 0 12px",
                fontSize: 13,
                color: "var(--color-muted)",
              }}
            >
              Reorder the sequence of pickup and dropoff points from 1st (Start
              Station) to Nth (Final Destination).
            </p>
            <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
              {orderedPoints.map((pt, idx) => {
                const isFirst = idx === 0;
                const isLast = idx === orderedPoints.length - 1;
                return (
                  <div
                    key={pt.id}
                    style={{
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "space-between",
                      padding: "10px 14px",
                      background: "var(--color-panel)",
                      border: "1px solid var(--color-border)",
                      borderRadius: 10,
                      gap: 10,
                    }}
                  >
                    <div
                      style={{
                        display: "flex",
                        alignItems: "center",
                        gap: 10,
                        minWidth: 0,
                      }}
                    >
                      <span
                        className="mono"
                        style={{
                          minWidth: 26,
                          height: 26,
                          borderRadius: "50%",
                          background: isFirst
                            ? "var(--color-secondary)"
                            : isLast
                              ? "var(--color-primary)"
                              : "var(--color-muted)",
                          color: "var(--color-on-primary)",
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "center",
                          fontSize: 12,
                          fontWeight: 700,
                          flexShrink: 0,
                        }}
                      >
                        {idx + 1}
                      </span>
                      <div style={{ minWidth: 0 }}>
                        <span
                          style={{
                            fontSize: 13,
                            fontWeight: 700,
                            color: "var(--color-primary)",
                            display: "block",
                          }}
                        >
                          {isFirst
                            ? "1st (Start Station): "
                            : isLast
                              ? `${idx + 1}th (Final Station): `
                              : `${idx + 1}th Station: `}
                          {pt.type === "pickup" ? "Pickup" : "Dropoff"} · Trip #
                          {pt.tripNumber ?? "—"}
                        </span>
                        <span
                          style={{
                            fontSize: 12,
                            color: "var(--color-muted)",
                            display: "block",
                            textOverflow: "ellipsis",
                            overflow: "hidden",
                            whiteSpace: "nowrap",
                          }}
                        >
                          {pt.address}
                        </span>
                      </div>
                    </div>

                    <div style={{ display: "flex", gap: 4, flexShrink: 0 }}>
                      <button
                        type="button"
                        onClick={() => movePoint(idx, "up")}
                        disabled={isFirst}
                        style={{
                          padding: "4px 8px",
                          borderRadius: 6,
                          border: "1px solid var(--color-border)",
                          background: "var(--color-panel)",
                          fontSize: 12,
                          fontWeight: 600,
                          cursor: isFirst ? "default" : "pointer",
                          opacity: isFirst ? 0.4 : 1,
                        }}
                      >
                        ↑ Up
                      </button>
                      <button
                        type="button"
                        onClick={() => movePoint(idx, "down")}
                        disabled={isLast}
                        style={{
                          padding: "4px 8px",
                          borderRadius: 6,
                          border: "1px solid var(--color-border)",
                          background: "var(--color-panel)",
                          fontSize: 12,
                          fontWeight: 600,
                          cursor: isLast ? "default" : "pointer",
                          opacity: isLast ? 0.4 : 1,
                        }}
                      >
                        ↓ Down
                      </button>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {feedback && (
          <div
            style={{
              padding: "12px 14px",
              borderRadius: 12,
              background:
                feedback.type === "success"
                  ? "var(--color-success-tint)"
                  : "var(--color-warning-tint)",
              color:
                feedback.type === "success"
                  ? "var(--color-success)"
                  : "var(--color-warning)",
              fontWeight: 600,
              fontSize: 14,
            }}
          >
            {feedback.message}
          </div>
        )}

        <button type="submit" disabled={submitting} className="submit-btn">
          {submitting ? "Creating ride…" : "Create ride"}
        </button>
      </form>
    </section>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import {
  AlertTriangle,
  Bell,
  Check,
  CheckCircle2,
  Info,
  Megaphone,
  MessageCircle,
  Pencil,
  Plus,
  Send,
  Trash2,
  Users,
} from "lucide-react";

interface Recipient {
  id: string;
  name: string;
  email?: string;
  phone?: string;
  role: "passenger" | "driver";
  createdAt: string;
}

interface NotificationTemplate {
  id: string;
  name: string;
  title: string;
  message: string;
  titleAr: string;
  messageAr: string;
  icon: string;
  style: string;
  linkUrl: string;
  linkLabel: string;
  linkLabelAr: string;
}

interface BroadcastStatusItem {
  id: string;
  title: string;
  body: string;
  source: "broadcast" | "activity";
  createdAt: string;
  recipient: {
    id: string;
    name: string;
    email?: string;
    phone?: string;
    role?: "passenger" | "driver" | "admin";
  };
  status: "pending" | "delivered" | "seen" | "read";
  deliveredAt?: string | null;
  seenAt?: string | null;
  readAt?: string | null;
}

const ICON_OPTIONS = [
  { value: "bell", label: "Bell", Icon: Bell },
  { value: "info", label: "Info", Icon: Info },
  { value: "megaphone", label: "Announcement", Icon: Megaphone },
  { value: "check", label: "Success", Icon: CheckCircle2 },
  { value: "alert", label: "Alert", Icon: AlertTriangle },
] as const;

const STYLE_OPTIONS = [
  {
    value: "info",
    label: "Information",
    color: "#0B1E3D",
    background: "#EEF5FF",
  },
  {
    value: "success",
    label: "Success",
    color: "#087F5B",
    background: "#E7F8F1",
  },
  {
    value: "warning",
    label: "Warning",
    color: "#A15C00",
    background: "#FFF5DB",
  },
  { value: "urgent", label: "Urgent", color: "#B42318", background: "#FFF0EF" },
] as const;

function buildWhatsAppLink(phone?: string) {
  if (!phone) return "";
  const digits = phone.replace(/\D/g, "");
  if (!digits) return "";
  return `https://wa.me/${digits}`;
}

export default function NotificationCenter({
  recipients,
  initialTemplates,
  initialBroadcasts = [],
}: {
  recipients: Recipient[];
  initialTemplates: NotificationTemplate[];
  initialBroadcasts?: BroadcastStatusItem[];
}) {
  const [templates, setTemplates] = useState(initialTemplates);
  const [broadcasts, setBroadcasts] =
    useState<BroadcastStatusItem[]>(initialBroadcasts);
  const [templateId, setTemplateId] = useState("");
  const [templateName, setTemplateName] = useState("");
  const [audience, setAudience] = useState("all");
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [roleFilter, setRoleFilter] = useState<"all" | "passenger" | "driver">(
    "all",
  );
  const [title, setTitle] = useState("");
  const [message, setMessage] = useState("");
  const [titleAr, setTitleAr] = useState("");
  const [messageAr, setMessageAr] = useState("");
  const [historyFilters, setHistoryFilters] = useState({
    status: "all",
    role: "all",
    q: "",
    page: 1,
  });
  const [historyMeta, setHistoryMeta] = useState({
    total: 0,
    page: 1,
    pageSize: 5,
    totalPages: 1,
  });
  const [icon, setIcon] = useState("bell");
  const [style, setStyle] = useState("info");
  const [linkUrl, setLinkUrl] = useState("");
  const [linkLabel, setLinkLabel] = useState("");
  const [linkLabelAr, setLinkLabelAr] = useState("");
  const [createdFrom, setCreatedFrom] = useState("");
  const [createdTo, setCreatedTo] = useState("");
  const [sending, setSending] = useState(false);
  const [feedback, setFeedback] = useState<{
    type: "success" | "error";
    text: string;
  } | null>(null);

  const visibleRecipients = useMemo(
    () =>
      recipients.filter(
        (recipient) => roleFilter === "all" || recipient.role === roleFilter,
      ),
    [recipients, roleFilter],
  );
  const selectedIcon =
    ICON_OPTIONS.find((option) => option.value === icon) ?? ICON_OPTIONS[0];
  const SelectedIcon = selectedIcon.Icon;
  const selectedStyle =
    STYLE_OPTIONS.find((option) => option.value === style) ?? STYLE_OPTIONS[0];

  const selectedTemplate = templates.find(
    (template) => template.id === templateId,
  );

  async function refreshBroadcasts() {
    try {
      const params = new URLSearchParams({
        limit: "5",
        page: String(historyFilters.page),
      });
      if (historyFilters.status !== "all")
        params.set("status", historyFilters.status);
      if (historyFilters.role !== "all")
        params.set("role", historyFilters.role);
      if (historyFilters.q.trim()) params.set("q", historyFilters.q.trim());
      const response = await fetch(
        `/api/admin/notifications?${params.toString()}`,
        {
          cache: "no-store",
        },
      );
      if (!response.ok) return;
      const result = await response.json();
      const next = Array.isArray(result.data) ? result.data : [];
      setBroadcasts(
        next.filter((item: BroadcastStatusItem) => item.source === "broadcast"),
      );
      setHistoryMeta({
        total: Number(result.meta?.total ?? next.length),
        page: Number(result.meta?.page ?? historyFilters.page),
        pageSize: Number(result.meta?.pageSize ?? 5),
        totalPages: Number(result.meta?.totalPages ?? 1),
      });
    } catch (error) {
      console.error("Failed to refresh admin notifications:", error);
    }
  }

  const applyHistoryFilters = (next: Partial<typeof historyFilters>) => {
    setHistoryFilters((current) => ({
      ...current,
      ...next,
      page: next.page ?? 1,
    }));
  };

  useEffect(() => {
    void refreshBroadcasts();
  }, [
    historyFilters.status,
    historyFilters.role,
    historyFilters.page,
    historyFilters.q,
  ]);

  function applyTemplate(id: string) {
    const template = templates.find((item) => item.id === id);
    setTemplateId(id);
    if (!template) return;
    setTemplateName(template.name);
    setTitle(template.title);
    setMessage(template.message);
    setTitleAr(template.titleAr);
    setMessageAr(template.messageAr);
    setIcon(template.icon);
    setStyle(template.style);
    setLinkUrl(template.linkUrl);
    setLinkLabel(template.linkLabel);
    setLinkLabelAr(template.linkLabelAr);
  }

  async function saveTemplate() {
    if (
      !templateName.trim() ||
      !title.trim() ||
      !message.trim() ||
      !titleAr.trim() ||
      !messageAr.trim()
    ) {
      setFeedback({
        type: "error",
        text: "Template name, title, and message are required.",
      });
      return;
    }
    const payload = {
      name: templateName,
      title,
      message,
      titleAr,
      messageAr,
      icon,
      style,
      linkUrl,
      linkLabel,
      linkLabelAr,
    };
    const response = await fetch(
      templateId
        ? `/api/admin/notifications/templates/${templateId}`
        : "/api/admin/notifications/templates",
      {
        method: templateId ? "PATCH" : "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      },
    );
    const result = await response.json();
    if (!response.ok) {
      setFeedback({
        type: "error",
        text: result.error ?? "Could not save template",
      });
      return;
    }
    const saved = result.data as NotificationTemplate;
    setTemplates((current) =>
      templateId
        ? current.map((item) => (item.id === saved.id ? saved : item))
        : [...current, saved],
    );
    setTemplateId(saved.id);
    setFeedback({ type: "success", text: "Template saved." });
  }

  async function deleteTemplate() {
    if (
      !selectedTemplate ||
      !window.confirm(`Delete template "${selectedTemplate.name}"?`)
    )
      return;
    const response = await fetch(
      `/api/admin/notifications/templates/${selectedTemplate.id}`,
      { method: "DELETE" },
    );
    if (!response.ok) {
      const result = await response.json();
      setFeedback({
        type: "error",
        text: result.error ?? "Could not delete template",
      });
      return;
    }
    setTemplates((current) =>
      current.filter((item) => item.id !== selectedTemplate.id),
    );
    setTemplateId("");
    setTemplateName("");
    setFeedback({ type: "success", text: "Template deleted." });
  }

  function toggleRecipient(id: string) {
    setSelectedIds((current) =>
      current.includes(id)
        ? current.filter((item) => item !== id)
        : [...current, id],
    );
  }

  function selectVisible() {
    const ids = visibleRecipients.map((recipient) => recipient.id);
    setSelectedIds((current) => Array.from(new Set([...current, ...ids])));
  }

  function clearVisible() {
    const ids = new Set(visibleRecipients.map((recipient) => recipient.id));
    setSelectedIds((current) => current.filter((id) => !ids.has(id)));
  }

  async function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setFeedback(null);
    setSending(true);
    try {
      const response = await fetch("/api/admin/notifications", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          title,
          message,
          titleAr,
          messageAr,
          audience,
          userIds: audience === "selected" ? selectedIds : undefined,
          icon,
          style,
          linkUrl,
          linkLabel,
          linkLabelAr,
          createdFrom: audience === "created" ? createdFrom : undefined,
          createdTo: audience === "created" ? createdTo : undefined,
        }),
      });
      const result = await response.json();
      if (!response.ok)
        throw new Error(result.error ?? "Could not send notification");

      setFeedback({
        type: "success",
        text: `Notification sent to ${result.sent} user${result.sent === 1 ? "" : "s"}.`,
      });
      await refreshBroadcasts();
      setTitle("");
      setMessage("");
      setLinkUrl("");
      setLinkLabel("");
      setSelectedIds([]);
    } catch (error) {
      setFeedback({
        type: "error",
        text:
          error instanceof Error
            ? error.message
            : "Could not send notification",
      });
    } finally {
      setSending(false);
    }
  }

  return (
    <section style={{ marginTop: 22 }}>
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 12,
          marginBottom: 14,
        }}
      >
        <div
          style={{
            width: 42,
            height: 42,
            borderRadius: 12,
            background: "var(--color-secondary-tint)",
            color: "var(--color-secondary)",
            display: "grid",
            placeItems: "center",
          }}
        >
          <Bell size={21} />
        </div>
        <div>
          <h2
            style={{ margin: 0, color: "var(--color-primary)", fontSize: 20 }}
          >
            Notification center
          </h2>
          <p
            style={{
              margin: "3px 0 0",
              color: "var(--color-muted)",
              fontSize: 13,
            }}
          >
            Send targeted in-app notifications to passengers and drivers.
          </p>
        </div>
      </div>

      <form
        onSubmit={submit}
        style={{
          display: "grid",
          gridTemplateColumns: "minmax(0, 1.1fr) minmax(280px, .9fr)",
          gap: 18,
        }}
      >
        <div style={{ display: "grid", gap: 14 }}>
          <div className="admin-notification-panel">
            <div className="admin-notification-panel-title">
              <Bell size={16} /> Ready templates
            </div>
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "minmax(0, 1fr) auto auto auto",
                gap: 8,
              }}
            >
              <select
                className="admin-notification-template-select"
                value={templateId}
                onChange={(event) => applyTemplate(event.target.value)}
              >
                <option value="">Start from scratch</option>
                {templates.map((template) => (
                  <option key={template.id} value={template.id}>
                    {template.name}
                  </option>
                ))}
              </select>
              <button
                type="button"
                className="admin-notification-icon-button"
                onClick={() => {
                  setTemplateId("");
                  setTemplateName("");
                }}
                title="New template"
                aria-label="New template"
              >
                <Plus size={16} />
              </button>
              <button
                type="button"
                className="admin-notification-icon-button"
                onClick={saveTemplate}
                title="Save template"
                aria-label="Save template"
              >
                <Pencil size={16} />
              </button>
              <button
                type="button"
                className="admin-notification-icon-button danger"
                onClick={deleteTemplate}
                disabled={!selectedTemplate}
                title="Delete template"
                aria-label="Delete template"
              >
                <Trash2 size={16} />
              </button>
            </div>
            <label className="admin-notification-label">
              Template name
              <input
                maxLength={80}
                value={templateName}
                onChange={(event) => setTemplateName(event.target.value)}
                placeholder="Name this template before saving"
              />
            </label>
          </div>
          <div className="admin-notification-panel">
            <div className="admin-notification-panel-title">
              <Send size={16} /> Compose message
            </div>
            <label className="admin-notification-label">
              Title
              <input
                required
                maxLength={120}
                value={title}
                onChange={(event) => setTitle(event.target.value)}
                placeholder="Service update"
              />
            </label>
            <label className="admin-notification-label">
              Message
              <textarea
                required
                maxLength={1000}
                rows={5}
                value={message}
                onChange={(event) => setMessage(event.target.value)}
                placeholder="Write the notification message..."
              />
            </label>
            <label className="admin-notification-label" dir="rtl">
              العنوان بالعربية
              <input
                required
                maxLength={120}
                value={titleAr}
                onChange={(event) => setTitleAr(event.target.value)}
                placeholder="عنوان الإشعار"
              />
            </label>
            <label className="admin-notification-label" dir="rtl">
              الرسالة بالعربية
              <textarea
                required
                maxLength={1000}
                rows={5}
                value={messageAr}
                onChange={(event) => setMessageAr(event.target.value)}
                placeholder="اكتب رسالة الإشعار بالعربية..."
              />
            </label>
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "1fr 1fr",
                gap: 12,
              }}
            >
              <label className="admin-notification-label">
                Icon
                <select
                  value={icon}
                  onChange={(event) => setIcon(event.target.value)}
                >
                  {ICON_OPTIONS.map(({ value, label }) => (
                    <option key={value} value={value}>
                      {label}
                    </option>
                  ))}
                </select>
              </label>
              <label className="admin-notification-label">
                Style
                <select
                  value={style}
                  onChange={(event) => setStyle(event.target.value)}
                >
                  {STYLE_OPTIONS.map(({ value, label }) => (
                    <option key={value} value={value}>
                      {label}
                    </option>
                  ))}
                </select>
              </label>
            </div>
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "1.2fr .8fr",
                gap: 12,
              }}
            >
              <label className="admin-notification-label">
                App page or URL
                <input
                  maxLength={300}
                  value={linkUrl}
                  onChange={(event) => setLinkUrl(event.target.value)}
                  placeholder="/my-trips or https://..."
                />
              </label>
              <label className="admin-notification-label">
                Button label
                <input
                  maxLength={40}
                  value={linkLabel}
                  onChange={(event) => setLinkLabel(event.target.value)}
                  placeholder="View details"
                />
              </label>
            </div>
            <label className="admin-notification-label" dir="rtl">
              نص الزر بالعربية
              <input
                maxLength={40}
                value={linkLabelAr}
                onChange={(event) => setLinkLabelAr(event.target.value)}
                placeholder="عرض التفاصيل"
              />
            </label>
          </div>

          <div
            className="admin-notification-preview"
            style={{
              borderColor: selectedStyle.color,
              background: selectedStyle.background,
            }}
          >
            <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
              <span
                className="admin-notification-preview-icon"
                style={{ color: selectedStyle.color }}
              >
                <SelectedIcon size={18} />
              </span>
              <strong>{title || "Notification title"}</strong>
            </div>
            <p>{message || "Your notification preview will appear here."}</p>
            {linkUrl && linkLabel ? (
              <span className="admin-notification-preview-link">
                {linkLabel}
              </span>
            ) : null}
          </div>
        </div>

        <div style={{ display: "grid", gap: 14, alignContent: "start" }}>
          <div className="admin-notification-panel">
            <div className="admin-notification-panel-title">
              <Users size={16} /> Recipients
            </div>
            <label className="admin-notification-label">
              Audience
              <select
                value={audience}
                onChange={(event) => setAudience(event.target.value)}
              >
                <option value="all">All passengers and drivers</option>
                <option value="passengers">All passengers</option>
                <option value="drivers">All drivers</option>
                <option value="created">Users created during dates</option>
                <option value="selected">Selected users</option>
              </select>
            </label>
            {audience === "created" && (
              <div
                style={{
                  display: "grid",
                  gridTemplateColumns: "1fr 1fr",
                  gap: 10,
                }}
              >
                <label className="admin-notification-label">
                  From
                  <input
                    type="date"
                    value={createdFrom}
                    onChange={(event) => setCreatedFrom(event.target.value)}
                  />
                </label>
                <label className="admin-notification-label">
                  To
                  <input
                    type="date"
                    value={createdTo}
                    onChange={(event) => setCreatedTo(event.target.value)}
                  />
                </label>
              </div>
            )}
            {audience === "selected" && (
              <>
                <div
                  style={{
                    display: "flex",
                    gap: 7,
                    flexWrap: "wrap",
                    marginBottom: 9,
                  }}
                >
                  <button
                    type="button"
                    className={`admin-notification-filter ${roleFilter === "all" ? "active" : ""}`}
                    onClick={() => setRoleFilter("all")}
                  >
                    All
                  </button>
                  <button
                    type="button"
                    className={`admin-notification-filter ${roleFilter === "passenger" ? "active" : ""}`}
                    onClick={() => setRoleFilter("passenger")}
                  >
                    Passengers
                  </button>
                  <button
                    type="button"
                    className={`admin-notification-filter ${roleFilter === "driver" ? "active" : ""}`}
                    onClick={() => setRoleFilter("driver")}
                  >
                    Drivers
                  </button>
                  <button
                    type="button"
                    className="admin-notification-text-button"
                    onClick={selectVisible}
                  >
                    Select visible
                  </button>
                  <button
                    type="button"
                    className="admin-notification-text-button"
                    onClick={clearVisible}
                  >
                    Clear visible
                  </button>
                </div>
                <div className="admin-notification-recipient-list">
                  {visibleRecipients.map((recipient) => (
                    <label
                      key={recipient.id}
                      className="admin-notification-recipient"
                    >
                      <input
                        type="checkbox"
                        checked={selectedIds.includes(recipient.id)}
                        onChange={() => toggleRecipient(recipient.id)}
                      />
                      <span>
                        <strong>{recipient.name}</strong>
                        <small>
                          {recipient.role}{" "}
                          {recipient.email ? `· ${recipient.email}` : ""}
                        </small>
                      </span>
                    </label>
                  ))}
                </div>
                <small style={{ color: "var(--color-muted)" }}>
                  {selectedIds.length} selected
                </small>
              </>
            )}
          </div>

          {feedback && (
            <div
              style={{
                padding: "11px 13px",
                borderRadius: 9,
                background: feedback.type === "success" ? "#E8F8F1" : "#FFF0EF",
                color: feedback.type === "success" ? "#087F5B" : "#B42318",
                fontSize: 13,
                fontWeight: 700,
              }}
            >
              {feedback.type === "success" ? (
                <Check
                  size={15}
                  style={{ verticalAlign: "-3px", marginRight: 5 }}
                />
              ) : (
                <AlertTriangle
                  size={15}
                  style={{ verticalAlign: "-3px", marginRight: 5 }}
                />
              )}
              {feedback.text}
            </div>
          )}
          <button
            type="submit"
            disabled={
              sending || (audience === "selected" && selectedIds.length === 0)
            }
            className="admin-notification-submit"
          >
            <Send size={16} />
            {sending ? "Sending..." : "Send notification"}
          </button>
        </div>
      </form>

      <div
        className="admin-notification-panel"
        style={{ marginTop: 18, marginBottom: 12 }}
      >
        <div className="admin-notification-panel-title">
          <Bell size={16} /> Recent sends
        </div>
        <div className="admin-notification-history-toolbar">
          <input
            value={historyFilters.q}
            onChange={(event) =>
              applyHistoryFilters({ q: event.target.value, page: 1 })
            }
            placeholder="Search by name, email, phone"
            aria-label="Search recent sends"
          />
          <select
            value={historyFilters.status}
            onChange={(event) =>
              applyHistoryFilters({ status: event.target.value, page: 1 })
            }
            aria-label="Filter recent sends by status"
          >
            <option value="all">All statuses</option>
            <option value="pending">Pending</option>
            <option value="delivered">Delivered</option>
            <option value="seen">Seen</option>
            <option value="read">Read</option>
          </select>
          <select
            value={historyFilters.role}
            onChange={(event) =>
              applyHistoryFilters({ role: event.target.value, page: 1 })
            }
            aria-label="Filter recent sends by role"
          >
            <option value="all">All roles</option>
            <option value="passenger">Passengers</option>
            <option value="driver">Drivers</option>
          </select>
        </div>
        {broadcasts.length === 0 ? (
          <p style={{ margin: 0, color: "var(--color-muted)", fontSize: 13 }}>
            No broadcasts match your filters yet.
          </p>
        ) : (
          <>
            <div className="admin-notification-history-list">
              {broadcasts.map((item) => {
                const whatsappHref = buildWhatsAppLink(item.recipient.phone);
                return (
                  <div
                    key={item.id}
                    className="admin-notification-history-item"
                  >
                    <div className="admin-notification-history-copy">
                      <strong>{item.title}</strong>
                      <small>{item.body}</small>
                      <span>
                        {item.recipient.name} · {item.recipient.role ?? "user"}
                      </span>
                      <time>{new Date(item.createdAt).toLocaleString()}</time>
                    </div>
                    <div className="admin-notification-history-meta">
                      <span
                        className={`admin-notification-status ${item.status}`}
                      >
                        {item.status}
                      </span>
                      {whatsappHref ? (
                        <a
                          href={whatsappHref}
                          target="_blank"
                          rel="noreferrer"
                          className="admin-notification-whatsapp"
                          aria-label={`WhatsApp ${item.recipient.name}`}
                          title={`Chat on WhatsApp with ${item.recipient.name}`}
                        >
                          <MessageCircle size={15} />
                        </a>
                      ) : null}
                    </div>
                  </div>
                );
              })}
            </div>
            <div className="admin-notification-pagination">
              <button
                type="button"
                onClick={() =>
                  applyHistoryFilters({
                    page: Math.max(1, historyFilters.page - 1),
                  })
                }
                disabled={historyFilters.page <= 1}
              >
                Previous
              </button>
              <span>
                Page {historyMeta.page} of {historyMeta.totalPages}
              </span>
              <button
                type="button"
                onClick={() =>
                  applyHistoryFilters({
                    page: Math.min(
                      historyMeta.totalPages,
                      historyFilters.page + 1,
                    ),
                  })
                }
                disabled={historyFilters.page >= historyMeta.totalPages}
              >
                Next
              </button>
            </div>
          </>
        )}
      </div>

      <style>{`
        .admin-notification-panel { background: #fff; border: 1px solid var(--color-border); border-radius: var(--radius-lg); padding: 18px; display: grid; gap: 13px; }
        .admin-notification-panel-title { display: flex; align-items: center; gap: 7px; color: var(--color-primary); font-size: 14px; font-weight: 800; }
        .admin-notification-label { display: grid; gap: 6px; color: var(--color-muted); font-size: 12px; font-weight: 700; }
        .admin-notification-label input, .admin-notification-label textarea, .admin-notification-label select { width: 100%; box-sizing: border-box; border: 1px solid var(--color-border); border-radius: 8px; padding: 10px 11px; background: #fff; color: var(--color-primary); font: inherit; font-size: 13px; outline: none; }
        .admin-notification-label textarea { resize: vertical; min-height: 112px; line-height: 1.5; }
        .admin-notification-label input:focus, .admin-notification-label textarea:focus, .admin-notification-label select:focus { border-color: var(--color-secondary); box-shadow: 0 0 0 3px rgba(0,194,168,.12); }
        .admin-notification-preview { border: 1px solid; border-radius: var(--radius-lg); padding: 16px; color: var(--color-primary); }
        .admin-notification-preview-icon { width: 34px; height: 34px; border-radius: 50%; background: rgba(255,255,255,.75); display: grid; place-items: center; }
        .admin-notification-preview p { margin: 10px 0 0; color: var(--color-muted); font-size: 13px; line-height: 1.5; }
        .admin-notification-preview-link { display: inline-block; margin-top: 12px; color: var(--color-secondary); font-size: 12px; font-weight: 800; }
        .admin-notification-filter, .admin-notification-text-button { border: 1px solid var(--color-border); background: #fff; color: var(--color-muted); border-radius: 999px; padding: 6px 9px; font: inherit; font-size: 11px; font-weight: 700; cursor: pointer; }
        .admin-notification-filter.active { background: var(--color-primary); color: #fff; border-color: var(--color-primary); }
        .admin-notification-text-button { border: 0; color: var(--color-secondary); padding-inline: 3px; }
        .admin-notification-recipient-list { max-height: 220px; overflow-y: auto; border: 1px solid var(--color-border); border-radius: 8px; }
        .admin-notification-recipient { display: flex; align-items: center; gap: 9px; padding: 9px 10px; border-bottom: 1px solid #f0f2f4; cursor: pointer; }
        .admin-notification-recipient:last-child { border-bottom: 0; }
        .admin-notification-recipient span { display: grid; gap: 2px; min-width: 0; }
        .admin-notification-recipient strong { color: var(--color-primary); font-size: 12px; }
        .admin-notification-recipient small { color: var(--color-muted); font-size: 11px; }
        .admin-notification-submit { border: 0; border-radius: 9px; background: var(--color-primary); color: #fff; display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 44px; font: inherit; font-size: 13px; font-weight: 800; cursor: pointer; }
        .admin-notification-submit:disabled { opacity: .5; cursor: not-allowed; }
        .admin-notification-history-toolbar { display: grid; grid-template-columns: minmax(0, 1.3fr) minmax(120px, 0.7fr) minmax(120px, 0.7fr); gap: 8px; }
        .admin-notification-history-toolbar input, .admin-notification-history-toolbar select { width: 100%; box-sizing: border-box; min-height: 38px; border: 1px solid var(--color-border); border-radius: 8px; background: #fff; color: var(--color-primary); font: inherit; font-size: 12px; padding: 0 10px; }
        .admin-notification-history-list { display: grid; gap: 10px; }
        .admin-notification-history-item { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; padding: 12px; border: 1px solid var(--color-border); border-radius: 10px; background: #fafbfc; }
        .admin-notification-history-copy { display: grid; gap: 4px; min-width: 0; }
        .admin-notification-history-copy strong { color: var(--color-primary); font-size: 13px; }
        .admin-notification-history-copy small, .admin-notification-history-copy span, .admin-notification-history-copy time { color: var(--color-muted); font-size: 11px; }
        .admin-notification-history-copy small { display: block; max-width: 100%; overflow-wrap: anywhere; }
        .admin-notification-history-meta { display: flex; align-items: center; gap: 8px; flex-shrink: 0; }
        .admin-notification-status { display: inline-flex; align-items: center; justify-content: center; min-width: 72px; padding: 4px 8px; border-radius: 999px; font-size: 10px; font-weight: 800; text-transform: capitalize; }
        .admin-notification-status.pending { background: #fff3db; color: #a15c00; }
        .admin-notification-status.delivered { background: #eaf3ff; color: #0b59b5; }
        .admin-notification-status.seen, .admin-notification-status.read { background: #e8f8f1; color: #087f5b; }
        .admin-notification-whatsapp { display: inline-flex; align-items: center; justify-content: center; width: 30px; height: 30px; border-radius: 50%; background: #dffae9; color: #0a9b5f; }
        .admin-notification-pagination { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-top: 6px; }
        .admin-notification-pagination button { border: 1px solid var(--color-border); background: #fff; color: var(--color-primary); border-radius: 8px; min-height: 34px; padding: 0 12px; font: inherit; font-size: 12px; font-weight: 700; cursor: pointer; }
        .admin-notification-pagination button:disabled { opacity: .45; cursor: not-allowed; }
        .admin-notification-pagination span { color: var(--color-muted); font-size: 12px; }
        .admin-notification-template-select { min-width: 0; border: 1px solid var(--color-border); border-radius: 8px; padding: 10px 11px; background: #fff; color: var(--color-primary); font: inherit; font-size: 13px; }
        .admin-notification-icon-button { width: 38px; height: 38px; border: 1px solid var(--color-border); border-radius: 8px; background: #fff; color: var(--color-primary); display: grid; place-items: center; cursor: pointer; }
        .admin-notification-icon-button:hover { border-color: var(--color-secondary); color: var(--color-secondary); }
        .admin-notification-icon-button.danger { color: var(--color-danger); }
        .admin-notification-icon-button:disabled { opacity: .45; cursor: not-allowed; }
        @media (max-width: 850px) { form:has(.admin-notification-panel) { grid-template-columns: 1fr !important; } }
      `}</style>
    </section>
  );
}

