"use client";

import { useEffect, useRef } from "react";
import { OSM_THEMES, type OsmMapThemeName } from "@/lib/config/mapSettings";

type LeafletModule = typeof import("leaflet");

export interface OsmPoint {
  lat: number;
  lng: number;
}

interface ZonePreviewSettings {
  showZones: boolean;
  showZoneLabels: boolean;
  maskOutsideZones: boolean;
  regionCode: "EG-CAIRO" | "SA" | "AE-ABU-DHABI";
}

interface OsmMapCanvasProps {
  center?: OsmPoint;
  zoom?: number;
  className?: string;
  style?: React.CSSProperties;
  cursor?: string;
  theme?: OsmMapThemeName;
  zoneSettings?: ZonePreviewSettings;
  onReady?: (map: L.Map | null) => void;
  onClick?: (point: OsmPoint) => void;
}

const CAIRO = { lat: 30.0444, lng: 31.2357 };

async function loadZoneData() {
  const response = await fetch("/geo/zone_polygon.geojson");
  if (!response.ok)
    return [] as Array<{ geometry?: { type?: string; coordinates?: unknown } }>;
  const geojson = await response.json();
  return geojson.features ?? [];
}

export default function OsmMapCanvas({
  center = CAIRO,
  zoom = 11,
  className,
  style,
  cursor,
  theme = "app",
  zoneSettings,
  onReady,
  onClick,
}: OsmMapCanvasProps) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const leafletRef = useRef<LeafletModule | null>(null);
  const mapRef = useRef<any>(null);
  const overlayRef = useRef<any>(null);
  const zoneLayerRef = useRef<any>(null);
  const readyRef = useRef(onReady);
  const clickRef = useRef(onClick);
  const viewRef = useRef({ center, zoom });

  useEffect(() => {
    readyRef.current = onReady;
    clickRef.current = onClick;
    viewRef.current = { center, zoom };
  });

  useEffect(() => {
    if (!containerRef.current || mapRef.current) return;

    let cancelled = false;
    void import("leaflet").then((leafletModule) => {
      if (cancelled || !containerRef.current) return;
      const L = leafletModule.default ?? leafletModule;
      leafletRef.current = L;

      const { center: initialCenter, zoom: initialZoom } = viewRef.current;
      const map = L.map(containerRef.current, {
        center: [initialCenter.lat, initialCenter.lng],
        zoom: initialZoom,
        zoomControl: false,
        attributionControl: true,
      });
      L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
        attribution: "&copy; OpenStreetMap contributors",
        maxZoom: 19,
      }).addTo(map);
      map.on("click", (event: any) => {
        clickRef.current?.({ lat: event.latlng.lat, lng: event.latlng.lng });
      });
      overlayRef.current = L.layerGroup().addTo(map);
      zoneLayerRef.current = L.layerGroup().addTo(map);
      mapRef.current = map;
      readyRef.current?.(map);
    });

    return () => {
      cancelled = true;
      const map = mapRef.current;
      if (map) {
        readyRef.current?.(null);
        overlayRef.current?.clearLayers();
        zoneLayerRef.current?.clearLayers();
        overlayRef.current?.remove();
        zoneLayerRef.current?.remove();
        map.remove();
      }
      mapRef.current = null;
      overlayRef.current = null;
      zoneLayerRef.current = null;
    };
  }, []);

  useEffect(() => {
    if (mapRef.current) mapRef.current.setView([center.lat, center.lng], zoom);
  }, [center.lat, center.lng, zoom]);

  useEffect(() => {
    const map = mapRef.current;
    const L = leafletRef.current;
    if (!map || !L) return;

    const themeColors = OSM_THEMES[theme];
    const overlay = overlayRef.current;
    const zoneLayer = zoneLayerRef.current;
    if (!overlay || !zoneLayer) return;

    let cancelled = false;

    const renderPreview = async () => {
      overlay.clearLayers();
      zoneLayer.clearLayers();

      if (
        !zoneSettings ||
        !zoneSettings.showZones ||
        zoneSettings.regionCode !== "EG-CAIRO"
      ) {
        return;
      }

      const features = await loadZoneData();
      if (
        cancelled ||
        !mapRef.current ||
        !overlayRef.current ||
        !zoneLayerRef.current
      )
        return;

      const primary = themeColors.primary;
      const secondary = themeColors.secondary;
      const accent = themeColors.accent;

      if (zoneSettings.maskOutsideZones) {
        const bounds = map.getBounds();
        const sw = bounds.getSouthWest();
        const ne = bounds.getNorthEast();
        L.polygon(
          [
            [sw.lat, sw.lng],
            [sw.lat, ne.lng],
            [ne.lat, ne.lng],
            [ne.lat, sw.lng],
            [sw.lat, sw.lng],
          ],
          {
            color: "transparent",
            fillColor: themeColors.surface,
            fillOpacity: 0.75,
            weight: 0,
          },
        ).addTo(overlayRef.current);
      }

      const activeZoneLayer = zoneLayerRef.current;
      features.forEach((feature: any) => {
        const geometry = feature?.geometry;
        if (!geometry || geometry.type !== "Polygon") return;
        const polygon = L.polygon(
          geometry.coordinates[0].map(([lng, lat]: [number, number]) => [
            lat,
            lng,
          ]),
          {
            color: primary,
            weight: 2,
            opacity: zoneSettings.showZones ? 1 : 0,
            fillColor: "transparent",
            fillOpacity: 0,
            dashArray: zoneSettings.showZoneLabels ? undefined : "6 6",
          },
        );
        polygon.addTo(activeZoneLayer);

        if (zoneSettings.showZoneLabels) {
          const center = polygon.getCenter();
          L.marker([center.lat, center.lng], {
            icon: L.divIcon({
              className: "",
              html: `<div style="background:${themeColors.surface};color:${secondary};border:1px solid ${primary};padding:4px 8px;border-radius:999px;font-size:11px;font-weight:700;white-space:nowrap;box-shadow:0 2px 8px rgba(0,0,0,0.08)">Zone</div>`,
              iconSize: [70, 24],
              iconAnchor: [35, 12],
            }),
            interactive: false,
          }).addTo(activeZoneLayer);
        }
      });

      if (zoneSettings.maskOutsideZones) {
        const bounds = map.getBounds();
        const sw = bounds.getSouthWest();
        const ne = bounds.getNorthEast();
        L.rectangle(
          [
            [sw.lat + 0.06, sw.lng + 0.06],
            [ne.lat - 0.06, ne.lng - 0.06],
          ],
          {
            color: accent,
            weight: 1,
            opacity: 0.45,
            fill: false,
          },
        ).addTo(activeZoneLayer);
      }
    };

    void renderPreview();

    return () => {
      cancelled = true;
      overlay.clearLayers();
      zoneLayer.clearLayers();
    };
  }, [theme, zoneSettings]);

  return (
    <div
      ref={containerRef}
      className={className}
      style={{ width: "100%", height: "100%", cursor, ...style }}
    />
  );
}

"use client";

import { useEffect, useState } from "react";
import L from "leaflet";
import OsmMapCanvas from "./OsmMapCanvas";
import { fitPoints, svgIcon } from "./leafletLayers";
import { useRouteOSRM } from "./useRouteOSRM";
import type { PickupPoint } from "@/types/driver";

interface Props {
  pickupPoints: PickupPoint[];
  destination: { lat: number; lng: number; label: string };
  height?: number;
}

const DEST_ICON = svgIcon(
  `<svg xmlns="http://www.w3.org/2000/svg" width="38" height="50"><path d="M19 0C8.5 0 0 8.5 0 19c0 13.7 19 34 19 34S38 32.7 38 19C38 8.5 29.5 0 19 0z" fill="#F5A623"/><circle cx="19" cy="19" r="8" fill="white"/><circle cx="19" cy="19" r="4.5" fill="#0B1E3D"/></svg>`,
  38,
  50,
);
function pickupIcon(index: number) {
  return svgIcon(
    `<svg xmlns="http://www.w3.org/2000/svg" width="32" height="32"><circle cx="16" cy="16" r="15" fill="#0B1E3D" stroke="#00C2A8" stroke-width="2.5"/><text x="16" y="21" text-anchor="middle" fill="white" font-size="12" font-weight="700" font-family="Arial">${index + 1}</text></svg>`,
    32,
    32,
    [16, 16],
  );
}

export default function PickupMapInnerOsm({
  pickupPoints,
  destination,
  height = 320,
}: Props) {
  const [map, setMap] = useState<L.Map | null>(null);
  const waypoints = [
    ...pickupPoints.map((point) => ({ lat: point.lat, lng: point.lng })),
    { lat: destination.lat, lng: destination.lng },
  ];
  const { route, loading, error } = useRouteOSRM(waypoints);
  const center = waypoints[0] ?? destination;

  useEffect(() => {
    if (!map) return;
    const layers = L.layerGroup().addTo(map);
    const path =
      route?.coordinates.map(([lat, lng]) => ({ lat, lng })) ?? waypoints;
    if (path.length > 1) {
      L.polyline(
        path.map((point) => [point.lat, point.lng]),
        { color: "#4361EE", weight: 14, opacity: 0.12 },
      ).addTo(layers);
      L.polyline(
        path.map((point) => [point.lat, point.lng]),
        {
          color: "#4361EE",
          weight: 5,
          opacity: 0.92,
          dashArray: error ? "8 8" : undefined,
        },
      ).addTo(layers);
    }
    pickupPoints.forEach((point, index) =>
      L.marker([point.lat, point.lng], { icon: pickupIcon(index) })
        .bindPopup(
          `<strong>${point.passenger_name}</strong><br/>${point.address}<br/>Pickup: +${point.pickup_time_offset} min from start`,
        )
        .addTo(layers),
    );
    L.marker([destination.lat, destination.lng], { icon: DEST_ICON })
      .bindPopup(destination.label)
      .addTo(layers);
    fitPoints(map, path, 40);
    return () => {
      layers.remove();
    };
  }, [map, route, error, pickupPoints, destination, waypoints]);

  return (
    <div style={{ height, position: "relative" }}>
      <OsmMapCanvas center={center} zoom={13} onReady={setMap} />
      {loading && (
        <div
          style={{
            position: "absolute",
            inset: 0,
            zIndex: 10,
            display: "grid",
            placeItems: "center",
            background: "rgba(239,247,246,.75)",
            color: "#5A6A7A",
            fontSize: 14,
          }}
        >
          Loading route...
        </div>
      )}
      {error && !loading && (
        <div
          style={{
            position: "absolute",
            top: 8,
            left: "50%",
            transform: "translateX(-50%)",
            zIndex: 10,
            background: "#FFF3E0",
            border: "1px solid #F39C12",
            borderRadius: 6,
            padding: "4px 12px",
            fontSize: 12,
            color: "#7a4d00",
          }}
        >
          Road route unavailable. Showing straight line.
        </div>
      )}
    </div>
  );
}

