"use client";

import { useEffect, useState } from "react";
import L from "leaflet";
import { MapPin } from "lucide-react";
import OsmMapCanvas from "@/components/map/OsmMapCanvas";
import { useClientLocale } from "@/lib/i18n/client";
import {
  fitPoints,
  svgIcon,
  type LatLng,
} from "@/components/map/leafletLayers";

interface Props {
  pickup?: LatLng | null;
  dropoff?: LatLng | null;
  height?: number;
  rounded?: number;
  interactive?: boolean;
  stops?: LatLng[];
  stations?: LatLng[];
}

const PICKUP_ICON = svgIcon(
  `<svg xmlns="http://www.w3.org/2000/svg" width="36" height="36"><circle cx="18" cy="18" r="16" fill="#0B1E3D" stroke="#00C2A8" stroke-width="3"/><circle cx="18" cy="18" r="6" fill="#fff"/></svg>`,
  36,
  36,
  [18, 18],
);
const DROPOFF_ICON = svgIcon(
  `<svg xmlns="http://www.w3.org/2000/svg" width="36" height="48"><path d="M18 0C8.06 0 0 8.06 0 18c0 13.05 18 32.4 18 32.4S36 31.05 36 18C36 8.06 27.94 0 18 0z" fill="#00C2A8"/><circle cx="18" cy="18" r="8" fill="#fff"/><circle cx="18" cy="18" r="4.5" fill="#0B1E3D"/></svg>`,
  36,
  48,
);
const STOP_ICON = svgIcon(
  `<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24"><circle cx="12" cy="12" r="10" fill="#F5A623" stroke="#fff" stroke-width="3"/></svg>`,
  24,
  24,
  [12, 12],
);
const STATION_ICON = svgIcon(
  `<svg xmlns="http://www.w3.org/2000/svg" width="26" height="26"><rect x="3" y="3" width="20" height="20" rx="6" fill="#00C2A8" stroke="#fff" stroke-width="3"/><rect x="9" y="9" width="8" height="8" rx="2" fill="#fff"/></svg>`,
  26,
  26,
  [13, 13],
);

function valid(point?: LatLng | null): point is LatLng {
  return !!point && Number.isFinite(point.lat) && Number.isFinite(point.lng);
}

function Placeholder({ height, rounded }: { height: number; rounded: number }) {
  const { t } = useClientLocale();
  return (
    <div
      style={{
        height,
        borderRadius: rounded,
        background: "#eef2f6",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        gap: 8,
        color: "#9aa7b4",
      }}
    >
      <MapPin size={18} />
      <span style={{ fontSize: 12, fontWeight: 600 }}>{t("map.route_preview")}</span>
    </div>
  );
}

export default function RouteMapOsm({
  pickup,
  dropoff,
  height = 150,
  rounded = 0,
  interactive = false,
  stops,
  stations,
}: Props) {
  const [map, setMap] = useState<L.Map | null>(null);
  const [path, setPath] = useState<LatLng[] | null>(null);
  const ok = valid(pickup) && valid(dropoff);

  useEffect(() => {
    if (!ok) return;
    let cancelled = false;
    const points = [...(stops ?? []), ...(stations ?? [])].filter(valid);
    const url = new URL("/api/directions", window.location.origin);
    url.searchParams.set("origin", `${pickup.lat},${pickup.lng}`);
    url.searchParams.set("dest", `${dropoff.lat},${dropoff.lng}`);
    if (points.length)
      url.searchParams.set(
        "waypoints",
        points.map((point) => `${point.lat},${point.lng}`).join("|"),
      );
    fetch(url)
      .then((response) => (response.ok ? response.json() : []))
      .then((data) => {
        if (!cancelled)
          setPath(
            data?.[0]?.coordinates?.map(([lat, lng]: [number, number]) => ({
              lat,
              lng,
            })) ?? null,
          );
      })
      .catch(() => !cancelled && setPath(null));
    return () => {
      cancelled = true;
    };
  }, [
    ok,
    pickup?.lat,
    pickup?.lng,
    dropoff?.lat,
    dropoff?.lng,
    JSON.stringify(stops ?? []),
    JSON.stringify(stations ?? []),
  ]);

  useEffect(() => {
    if (!map || !ok) return;
    const layers = L.layerGroup();
    const route = path?.length ? path : [pickup, dropoff];
    L.polyline(
      route.map((point) => [point.lat, point.lng]),
      { color: "#4361EE", weight: 12, opacity: 0.15 },
    ).addTo(layers);
    L.polyline(
      route.map((point) => [point.lat, point.lng]),
      { color: "#4361EE", weight: 5, opacity: 0.9 },
    ).addTo(layers);
    L.marker([pickup.lat, pickup.lng], { icon: PICKUP_ICON }).addTo(layers);
    L.marker([dropoff.lat, dropoff.lng], { icon: DROPOFF_ICON }).addTo(layers);
    stops
      ?.filter(valid)
      .forEach((point) =>
        L.marker([point.lat, point.lng], { icon: STOP_ICON }).addTo(layers),
      );
    stations
      ?.filter(valid)
      .forEach((point) =>
        L.marker([point.lat, point.lng], { icon: STATION_ICON }).addTo(layers),
      );
    layers.addTo(map);
    fitPoints(map, [
      ...route,
      ...(stops ?? []).filter(valid),
      ...(stations ?? []).filter(valid),
    ]);
    return () => {
      layers.remove();
    };
  }, [map, ok, pickup, dropoff, path, stops, stations]);

  if (!ok) return <Placeholder height={height} rounded={rounded} />;
  return (
    <div
      style={{
        height,
        borderRadius: rounded,
        overflow: "hidden",
        pointerEvents: interactive ? "auto" : "none",
      }}
    >
      <OsmMapCanvas center={pickup} zoom={13} onReady={setMap} />
    </div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { useClientLocale } from "@/lib/locale.client";
import { getStandaloneTripCancellationMode } from "@/lib/standaloneTripCancellation";
import {
  XCircle,
  AlertTriangle,
  Wallet,
  Clock,
  ShieldAlert,
  Loader2,
  CheckCircle2,
} from "lucide-react";

interface EvaluationResult {
  allowed: boolean;
  tierLabel: string;
  refundPercent: number;
  penaltyPercent: number;
  refundAmount: number;
  retainedAmount: number;
  daysBefore: number;
  timeStr: string;
  message?: string;
}

interface CancelTripModalProps {
  tripId: string;
  tripNumber?: number;
  date: string;
  priceEgp: number;
  status: string;
  isStandalone?: boolean;
  paymentStatus?: string;
  onCancelled?: () => void;
}

export default function CancelTripModal({
  tripId,
  tripNumber,
  date,
  priceEgp,
  status,
  isStandalone = false,
  paymentStatus = "pending",
  onCancelled,
}: CancelTripModalProps) {
  const router = useRouter();
  const { t } = useClientLocale();
  const [isOpen, setIsOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [evaluation, setEvaluation] = useState<EvaluationResult | null>(null);
  const [reason, setReason] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);
  const unpaidStandalone =
    isStandalone &&
    getStandaloneTripCancellationMode({
      id: tripId,
      status,
      paymentStatus,
    }).kind === "unpaid";

  // Exclude cancelled and completed trips
  if (status === "cancelled" || status === "completed" || status === "time_out") {
    return null;
  }

  async function openModal() {
    setIsOpen(true);
    setError(null);
    setSuccessMsg(null);
    setLoading(true);

    try {
      const res = await fetch(`/api/trips/${tripId}/cancel`);
      const json = await res.json();
      if (!res.ok) {
        throw new Error(
          json.errorCode === "REQUEST_NOT_CANCELLABLE"
            ? t("errors.REQUEST_NOT_CANCELLABLE")
            : json.errorCode === "TRIP_NOT_PAID"
              ? t("errors.TRIP_NOT_PAID")
            : json.error || "Failed to load cancellation details",
        );
      }
      setEvaluation(json.evaluation);
    } catch (err: any) {
      setError(err.message || "Failed to load cancellation policy");
    } finally {
      setLoading(false);
    }
  }

  async function handleConfirmCancel() {
    setError(null);
    setSubmitting(true);

    try {
      const res = await fetch(`/api/trips/${tripId}/cancel`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ reason }),
      });
      const json = await res.json();

      if (!res.ok) {
        throw new Error(
          json.errorCode === "REQUEST_NOT_CANCELLABLE"
            ? t("errors.REQUEST_NOT_CANCELLABLE")
            : json.errorCode === "TRIP_NOT_PAID"
              ? t("errors.TRIP_NOT_PAID")
            : json.error || "Failed to cancel trip",
        );
      }

      setSuccessMsg(json.message || "Trip cancelled successfully");
      setTimeout(() => {
        setIsOpen(false);
        if (onCancelled) onCancelled();
        router.refresh();
      }, 1200);
    } catch (err: any) {
      setError(err.message || "Cancellation failed");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <>
      <button
        type="button"
        onClick={openModal}
        className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold text-rose-600 bg-rose-50 hover:bg-rose-100 border border-rose-200 rounded-lg transition-colors cursor-pointer"
      >
        <XCircle size={14} />
        <span>Cancel Trip</span>
      </button>

      {isOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-950/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-2xl border border-slate-200 shadow-2xl max-w-md w-full overflow-hidden text-slate-900">
            {/* Header */}
            <div className="px-6 py-4 bg-slate-50 border-b border-slate-100 flex items-center justify-between">
              <div className="flex items-center gap-2">
                <ShieldAlert className="w-5 h-5 text-rose-500" />
                <h3 className="font-bold text-slate-900 text-base">
                  Cancel Trip {tripNumber ? `#${tripNumber}` : ""}
                </h3>
              </div>
              <button
                type="button"
                onClick={() => setIsOpen(false)}
                disabled={submitting}
                className="text-slate-400 hover:text-slate-600 text-lg leading-none p-1 rounded"
              >
                &times;
              </button>
            </div>

            {/* Body */}
            <div className="p-6 space-y-4">
              {error && (
                <div className="p-3 bg-rose-50 border border-rose-200 rounded-xl text-xs text-rose-700 font-medium flex items-center gap-2">
                  <AlertTriangle className="w-4 h-4 shrink-0 text-rose-500" />
                  <span>{error}</span>
                </div>
              )}

              {successMsg && (
                <div className="p-3 bg-emerald-50 border border-emerald-200 rounded-xl text-xs text-emerald-700 font-medium flex items-center gap-2">
                  <CheckCircle2 className="w-4 h-4 shrink-0 text-emerald-500" />
                  <span>{successMsg}</span>
                </div>
              )}

              {loading ? (
                <div className="py-8 flex flex-col items-center justify-center text-slate-400 gap-2">
                  <Loader2 className="w-6 h-6 animate-spin text-[#00C2A8]" />
                  <span className="text-xs font-medium">
                    {unpaidStandalone
                      ? "Loading cancellation options..."
                      : "Calculating cancellation policy & refund..."}
                  </span>
                </div>
              ) : evaluation ? (
                <>
                  {/* Trip Summary Card */}
                  <div className="bg-slate-50 rounded-xl p-3.5 border border-slate-100 flex items-center justify-between text-xs">
                    <div>
                      <span className="text-slate-500 block font-medium">Pickup Date</span>
                      <span className="font-bold text-slate-900">{date}</span>
                    </div>
                    <div className="text-right">
                      <span className="text-slate-500 block font-medium">Trip Fare</span>
                      <span className="font-bold text-slate-900">{priceEgp} EGP</span>
                    </div>
                  </div>

                  {unpaidStandalone ? (
                    <div className="space-y-3">
                      <p className="text-xs text-slate-600 leading-relaxed">
                        No payment has been taken. Cancelling will end this trip.
                      </p>
                      <div>
                        <label className="block text-xs font-semibold text-slate-700 mb-1">
                          Cancellation Reason (Optional)
                        </label>
                        <input
                          type="text"
                          value={reason}
                          onChange={(e) => setReason(e.target.value)}
                          placeholder="e.g. Schedule changed, emergency"
                          className="w-full text-xs px-3 py-2 bg-white border border-slate-300 rounded-lg focus:outline-none focus:border-[#00C2A8]"
                        />
                      </div>
                    </div>
                  ) : !evaluation.allowed ? (
                    <div className="p-4 bg-amber-50 border border-amber-200 rounded-xl space-y-2">
                      <div className="flex items-center gap-2 text-amber-800 font-bold text-xs">
                        <AlertTriangle className="w-4 h-4 text-amber-600" />
                        <span>Cancellation Blocked</span>
                      </div>
                      <p className="text-xs text-amber-700 leading-relaxed">
                        {evaluation.message ||
                          "Cancellation is blocked during the driver matching window (5:00 PM – 7:00 PM the day before pickup)."}
                      </p>
                    </div>
                  ) : (
                    <div className="space-y-3">
                      <div className="border border-slate-200 rounded-xl p-4 bg-slate-50/50 space-y-2.5">
                        <div className="flex items-center justify-between text-xs pb-2 border-b border-slate-200">
                          <span className="text-slate-600 font-medium">Refund Tier</span>
                          <span className="font-bold text-slate-900 capitalize">
                            {evaluation.tierLabel.replace(/_/g, " ")}
                          </span>
                        </div>

                        <div className="flex items-center justify-between text-xs">
                          <span className="text-slate-600 font-medium">Refund Percentage</span>
                          <span className="font-extrabold text-emerald-600">
                            {evaluation.refundPercent}%
                          </span>
                        </div>

                        <div className="flex items-center justify-between text-xs">
                          <span className="text-slate-600 font-medium">Penalty (Retained)</span>
                          <span className="font-bold text-rose-500">
                            {evaluation.penaltyPercent}% ({evaluation.retainedAmount} EGP)
                          </span>
                        </div>

                        <div className="flex items-center justify-between text-xs pt-2 border-t border-slate-200">
                          <span className="font-bold text-slate-900">Net Wallet Refund</span>
                          <span className="font-extrabold text-slate-900 text-sm text-[#00806E]">
                            + {evaluation.refundAmount} EGP
                          </span>
                        </div>
                      </div>

                      <div className="flex items-center gap-2 text-[11px] text-amber-800 bg-amber-50 border border-amber-200/80 p-2.5 rounded-lg">
                        <Wallet className="w-3.5 h-3.5 text-amber-600 shrink-0" />
                        <span>Your refund of {evaluation.refundAmount} EGP will be reviewed by an admin before it is credited to your wallet.</span>
                      </div>

                      <div>
                        <label className="block text-xs font-semibold text-slate-700 mb-1">
                          Cancellation Reason (Optional)
                        </label>
                        <input
                          type="text"
                          value={reason}
                          onChange={(e) => setReason(e.target.value)}
                          placeholder="e.g. Schedule changed, emergency"
                          className="w-full text-xs px-3 py-2 bg-white border border-slate-300 rounded-lg focus:outline-none focus:border-[#00C2A8]"
                        />
                      </div>
                    </div>
                  )}
                </>
              ) : null}
            </div>

            {/* Actions */}
            <div className="px-6 py-3.5 bg-slate-50 border-t border-slate-100 flex items-center justify-end gap-3">
              <button
                type="button"
                onClick={() => setIsOpen(false)}
                disabled={submitting}
                className="px-4 py-2 text-xs font-semibold text-slate-600 hover:text-slate-800 transition-colors cursor-pointer"
              >
                Keep Trip
              </button>

              {evaluation?.allowed && (
                <button
                  type="button"
                  onClick={handleConfirmCancel}
                  disabled={submitting || !!successMsg}
                  className="inline-flex items-center gap-2 px-5 py-2 text-xs font-bold text-white bg-rose-600 hover:bg-rose-700 disabled:opacity-50 rounded-xl transition-colors shadow-sm cursor-pointer"
                >
                  {submitting && <Loader2 className="w-3.5 h-3.5 animate-spin" />}
                  <span>{submitting ? "Cancelling..." : "Confirm Cancellation"}</span>
                </button>
              )}
            </div>
          </div>
        </div>
      )}
    </>
  );
}

